public inherited sharing class ContractLineItemPeriodService {
    public static void populatePeriodFields(List<ContractLineItem__c> records) {
        if (records == null) {
            return;
        }

        for (ContractLineItem__c record : records) {
            Date startDate = resolveStartDate(record);
            if (startDate == null) {
                continue;
            }

            String yearMonth = formatYearMonth(startDate);
            if (String.isBlank(record.ContractYearMonth__c)) {
                record.ContractYearMonth__c = yearMonth;
            }
            if (String.isBlank(record.Month__c)) {
                record.Month__c = yearMonth;
            }
            if (record.PeriodStartDate__c == null) {
                record.PeriodStartDate__c = startDate.toStartOfMonth();
            }
            if (record.PeriodEndDate__c == null) {
                record.PeriodEndDate__c = startDate.toStartOfMonth().addMonths(1).addDays(-1);
            }
        }
    }

    private static Date resolveStartDate(ContractLineItem__c record) {
        if (record.PeriodStartDate__c != null) {
            return record.PeriodStartDate__c;
        }

        String yearMonth = String.isBlank(record.ContractYearMonth__c)
            ? record.Month__c
            : record.ContractYearMonth__c;
        if (String.isBlank(yearMonth)) {
            record.addError('対象期間開始日、契約年月、対象年月のいずれかを入力してください。');
            return null;
        }

        List<String> parts = yearMonth.split('/');
        if (parts.size() != 2) {
            record.addError('契約年月または対象年月はYYYY/MM形式で入力してください。');
            return null;
        }

        try {
            Integer year = Integer.valueOf(parts[0]);
            Integer month = Integer.valueOf(parts[1]);
            if (parts[0].length() != 4 || month < 1 || month > 12) {
                record.addError('契約年月または対象年月は有効なYYYY/MM形式で入力してください。');
                return null;
            }
            return Date.newInstance(year, month, 1);
        } catch (Exception error) {
            record.addError('契約年月または対象年月は有効なYYYY/MM形式で入力してください。');
            return null;
        }
    }

    private static String formatYearMonth(Date targetDate) {
        String monthText = targetDate.month() < 10
            ? '0' + String.valueOf(targetDate.month())
            : String.valueOf(targetDate.month());
        return String.valueOf(targetDate.year()) + '/' + monthText;
    }
}

public with sharing class ContractMonthlyLineBatch
    implements Database.Batchable<SObject>, Schedulable {
    @TestVisible
    private static final String STATUS_ACTIVATED = 'Activated';
    @TestVisible
    private static final String UPDATE_MONTHLY = '月';
    @TestVisible
    private static final String UPDATE_YEARLY = '年';
    @TestVisible
    private static final Integer BILLING_UPDATE_DAY = 10;
    private static final Integer YEARLY_MONTH_COUNT = 12;

    private enum LineCreationTiming {
        ACTIVATION,
        SCHEDULED
    }

    private Date runDate;

    public ContractMonthlyLineBatch() {
        this(Date.today());
    }

    @TestVisible
    private ContractMonthlyLineBatch(Date runDate) {
        this.runDate = runDate;
    }

    public void execute(SchedulableContext context) {
        Database.executeBatch(new ContractMonthlyLineBatch(), 200);
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        if (!shouldRun(runDate)) {
            return Database.getQueryLocator([
                SELECT Id
                FROM Contract__c
                WHERE Id = null
            ]);
        }

        return Database.getQueryLocator([
            SELECT Id,
                   Name,
                   Account__c,
                   ContractName__c,
                   ContractUpdate__c,
                   Plan__c,
                   StartDate__c,
                   Status__c
            FROM Contract__c
            WHERE Status__c = :STATUS_ACTIVATED
              AND ContractUpdate__c IN (:UPDATE_MONTHLY, :UPDATE_YEARLY)
              AND StartDate__c != null
        ]);
    }

    public void execute(
        Database.BatchableContext context,
        List<Contract__c> contractRecords
    ) {
        createLines(contractRecords, LineCreationTiming.SCHEDULED, runDate);
    }

    public void finish(Database.BatchableContext context) {
    }

    public static void createInitialLinesForActivatedContracts(
        List<Contract__c> newRecords,
        Map<Id, Contract__c> oldMap
    ) {
        List<Contract__c> targetContracts = new List<Contract__c>();
        for (Contract__c contractRecord : newRecords) {
            if (!isLineCreationTarget(contractRecord)) {
                continue;
            }

            Contract__c oldRecord = oldMap == null ? null : oldMap.get(contractRecord.Id);
            if (oldRecord == null || oldRecord.Status__c != STATUS_ACTIVATED) {
                targetContracts.add(contractRecord);
            }
        }

        createLines(targetContracts, LineCreationTiming.ACTIVATION, Date.today());
    }

    @TestVisible
    private static Boolean shouldRun(Date targetDate) {
        return targetDate != null && targetDate.day() > BILLING_UPDATE_DAY;
    }

    private static void createLines(
        List<Contract__c> contractRecords,
        LineCreationTiming timing,
        Date targetDate
    ) {
        if (contractRecords.isEmpty()) {
            return;
        }

        Map<Id, Set<String>> existingLineKeysByContractId =
            getExistingLineKeysByContractId(contractRecords);
        Map<Id, InvoiceSummary> invoiceSummaryByContractId =
            getInvoiceSummaryByContractId(contractRecords);
        Map<Id, List<ContractLineItem__c>> templateLinesByContractId =
            getTemplateLinesByContractId(contractRecords);
        contractRecords = filterContractsWithLineSource(
            contractRecords,
            invoiceSummaryByContractId,
            templateLinesByContractId
        );
        if (contractRecords.isEmpty()) {
            return;
        }
        Map<String, ContractPeriod__c> periodByKey =
            getExistingPeriodsByKey(contractRecords);
        List<PendingLineGroup> pendingLineGroups = new List<PendingLineGroup>();
        List<ContractPeriod__c> periodsToInsert = new List<ContractPeriod__c>();
        List<ContractLineItem__c> linesToInsert = new List<ContractLineItem__c>();

        for (Contract__c contractRecord : contractRecords) {
            for (PeriodPlan periodPlan : buildTargetPeriods(
                contractRecord,
                timing,
                targetDate
            )) {
                String periodKey = buildPeriodKey(contractRecord.Id, periodPlan.periodStartDate);
                ContractPeriod__c periodRecord = periodByKey.get(periodKey);
                if (periodRecord == null) {
                    periodRecord = buildPeriod(contractRecord, periodPlan, timing);
                    periodsToInsert.add(periodRecord);
                    periodByKey.put(periodKey, periodRecord);
                }

                pendingLineGroups.add(new PendingLineGroup(
                    contractRecord,
                    periodRecord,
                    periodPlan
                ));
            }
        }

        if (!periodsToInsert.isEmpty()) {
            insert periodsToInsert;
        }

        for (PendingLineGroup groupRecord : pendingLineGroups) {
            List<ContractLineItem__c> templateLines =
                templateLinesByContractId.get(groupRecord.contractRecord.Id);
            if (templateLines != null && !templateLines.isEmpty()) {
                linesToInsert.addAll(buildLinesFromTemplates(
                    groupRecord,
                    collapseTemplateLines(templateLines),
                    existingLineKeysByContractId
                ));
            } else {
                linesToInsert.addAll(buildLinesFromInvoiceSummary(
                    groupRecord,
                    invoiceSummaryByContractId.get(groupRecord.contractRecord.Id),
                    existingLineKeysByContractId
                ));
            }
        }

        if (!linesToInsert.isEmpty()) {
            insert linesToInsert;
        }
    }

    private static Boolean isLineCreationTarget(Contract__c contractRecord) {
        return contractRecord.Status__c == STATUS_ACTIVATED
            && contractRecord.StartDate__c != null
            && (
                contractRecord.ContractUpdate__c == UPDATE_MONTHLY
                || contractRecord.ContractUpdate__c == UPDATE_YEARLY
            );
    }

    private static Map<Id, Set<String>> getExistingLineKeysByContractId(
        List<Contract__c> contractRecords
    ) {
        Set<Id> contractIds = new Set<Id>();
        for (Contract__c contractRecord : contractRecords) {
            contractIds.add(contractRecord.Id);
        }

        Map<Id, Set<String>> existingLineKeysByContractId =
            new Map<Id, Set<String>>();
        for (ContractLineItem__c line : [
            SELECT MasterContract__c,
                   ContractYearMonth__c,
                   ProductMaster__c,
                   QuotationLine__c
            FROM ContractLineItem__c
            WHERE MasterContract__c IN :contractIds
        ]) {
            if (!existingLineKeysByContractId.containsKey(line.MasterContract__c)) {
                existingLineKeysByContractId.put(
                    line.MasterContract__c,
                    new Set<String>()
                );
            }
            existingLineKeysByContractId.get(line.MasterContract__c).add(buildLineKey(line));
        }

        return existingLineKeysByContractId;
    }

    private static Map<Id, InvoiceSummary> getInvoiceSummaryByContractId(
        List<Contract__c> contractRecords
    ) {
        Set<Id> contractIds = new Set<Id>();
        for (Contract__c contractRecord : contractRecords) {
            contractIds.add(contractRecord.Id);
        }

        Map<Id, InvoiceSummary> invoiceSummaryByContractId =
            new Map<Id, InvoiceSummary>();
        for (AggregateResult result : [
            SELECT ParentContract__c contractId,
                   SUM(NumberOfPeople__c) peopleNumber,
                   SUM(TotalAmount__c) totalAmount
            FROM Invoice__c
            WHERE ParentContract__c IN :contractIds
            GROUP BY ParentContract__c
        ]) {
            invoiceSummaryByContractId.put(
                (Id) result.get('contractId'),
                new InvoiceSummary(
                    (Decimal) result.get('peopleNumber'),
                    (Decimal) result.get('totalAmount')
                )
            );
        }

        return invoiceSummaryByContractId;
    }

    private static Map<Id, List<ContractLineItem__c>> getTemplateLinesByContractId(
        List<Contract__c> contractRecords
    ) {
        Set<Id> contractIds = new Set<Id>();
        for (Contract__c contractRecord : contractRecords) {
            contractIds.add(contractRecord.Id);
        }

        Map<Id, List<ContractLineItem__c>> linesByContractId =
            new Map<Id, List<ContractLineItem__c>>();
        for (ContractLineItem__c line : [
            SELECT Id,
                   MasterContract__c,
                   ProductMaster__c,
                   QuotationLine__c,
                   RevenueAmount__c,
                   Total__c,
                   PeopleNumber__c,
                   MRR_Target__c,
                   ARR_Target__c,
                   Plan__c
            FROM ContractLineItem__c
            WHERE MasterContract__c IN :contractIds
              AND (InitialFee__c = false OR InitialFee__c = null)
            ORDER BY PeriodStartDate__c DESC, CreatedDate DESC
        ]) {
            if (!linesByContractId.containsKey(line.MasterContract__c)) {
                linesByContractId.put(line.MasterContract__c, new List<ContractLineItem__c>());
            }
            linesByContractId.get(line.MasterContract__c).add(line);
        }

        return linesByContractId;
    }

    private static Map<String, ContractPeriod__c> getExistingPeriodsByKey(
        List<Contract__c> contractRecords
    ) {
        Set<Id> contractIds = new Set<Id>();
        for (Contract__c contractRecord : contractRecords) {
            contractIds.add(contractRecord.Id);
        }

        Map<String, ContractPeriod__c> periodByKey = new Map<String, ContractPeriod__c>();
        for (ContractPeriod__c periodRecord : [
            SELECT Id,
                   Contract__c,
                   PeriodStartDate__c,
                   PeriodEndDate__c
            FROM ContractPeriod__c
            WHERE Contract__c IN :contractIds
        ]) {
            periodByKey.put(
                buildPeriodKey(periodRecord.Contract__c, periodRecord.PeriodStartDate__c),
                periodRecord
            );
        }

        return periodByKey;
    }

    private static List<Contract__c> filterContractsWithLineSource(
        List<Contract__c> contractRecords,
        Map<Id, InvoiceSummary> invoiceSummaryByContractId,
        Map<Id, List<ContractLineItem__c>> templateLinesByContractId
    ) {
        List<Contract__c> validContracts = new List<Contract__c>();
        List<String> contractNamesWithoutInvoice = new List<String>();
        for (Contract__c contractRecord : contractRecords) {
            List<ContractLineItem__c> templateLines = templateLinesByContractId.get(contractRecord.Id);
            Boolean hasTemplate = templateLines != null && !templateLines.isEmpty();
            Boolean hasInvoiceSummary = invoiceSummaryByContractId.containsKey(contractRecord.Id);
            if (hasTemplate || hasInvoiceSummary) {
                validContracts.add(contractRecord);
            } else {
                contractNamesWithoutInvoice.add(getContractDisplayName(contractRecord));
            }
        }

        if (!contractNamesWithoutInvoice.isEmpty()) {
            System.debug(LoggingLevel.WARN,
                'Skipped ContractMonthlyLineBatch targets because no invoice or contract monthly line source exists: '
                + String.join(contractNamesWithoutInvoice, ', ')
            );
        }
        return validContracts;
    }

    private static List<PeriodPlan> buildTargetPeriods(
        Contract__c contractRecord,
        LineCreationTiming timing,
        Date targetDate
    ) {
        Date startMonth = firstDayOfMonth(contractRecord.StartDate__c);

        if (timing == LineCreationTiming.ACTIVATION) {
            Integer monthCount = contractRecord.ContractUpdate__c == UPDATE_YEARLY
                ? YEARLY_MONTH_COUNT
                : 1;
            return new List<PeriodPlan>{
                new PeriodPlan(startMonth, monthCount)
            };
        }

        if (contractRecord.ContractUpdate__c == UPDATE_MONTHLY) {
            return new List<PeriodPlan>{
                new PeriodPlan(getScheduledMonthlyTargetMonth(startMonth, targetDate), 1)
            };
        }

        Date yearlyTargetMonth = getScheduledYearlyTargetMonth(startMonth, targetDate);
        if (yearlyTargetMonth == null) {
            return new List<PeriodPlan>();
        }

        return new List<PeriodPlan>{
            new PeriodPlan(yearlyTargetMonth, YEARLY_MONTH_COUNT)
        };
    }

    private static List<String> buildYearMonthRange(Date targetMonth, Integer monthCount) {
        List<String> yearMonths = new List<String>();
        for (Integer index = 0; index < monthCount; index++) {
            yearMonths.add(formatYearMonth(targetMonth.addMonths(index)));
        }

        return yearMonths;
    }

    private static Date getScheduledMonthlyTargetMonth(
        Date contractStartMonth,
        Date targetDate
    ) {
        Date nextMonth = firstDayOfMonth(targetDate).addMonths(1);
        return contractStartMonth > nextMonth ? contractStartMonth : nextMonth;
    }

    private static Date getScheduledYearlyTargetMonth(
        Date contractStartMonth,
        Date targetDate
    ) {
        Date nextMonth = firstDayOfMonth(targetDate).addMonths(1);
        if (nextMonth.month() != contractStartMonth.month()) {
            return null;
        }

        Date renewalStartMonth = Date.newInstance(
            nextMonth.year(),
            contractStartMonth.month(),
            1
        );
        return renewalStartMonth > contractStartMonth ? renewalStartMonth : null;
    }

    private static Date firstDayOfMonth(Date sourceDate) {
        return Date.newInstance(sourceDate.year(), sourceDate.month(), 1);
    }

    private static String formatYearMonth(Date sourceDate) {
        return String.valueOf(sourceDate.year()) + '/' + String.valueOf(sourceDate.month()).leftPad(2, '0');
    }

    private static String getContractDisplayName(Contract__c contractRecord) {
        return String.isBlank(contractRecord.ContractName__c)
            ? contractRecord.Name
            : contractRecord.ContractName__c;
    }

    private static List<ContractLineItem__c> buildLinesFromTemplates(
        PendingLineGroup groupRecord,
        List<ContractLineItem__c> templateLines,
        Map<Id, Set<String>> existingLineKeysByContractId
    ) {
        List<ContractLineItem__c> lines = new List<ContractLineItem__c>();
        for (String yearMonth : buildYearMonthRange(
            groupRecord.periodPlan.periodStartDate,
            groupRecord.periodPlan.monthCount
        )) {
            Date monthStart = parseYearMonth(yearMonth);
            for (ContractLineItem__c templateLine : templateLines) {
                String lineKey = buildLineKey(yearMonth, templateLine.ProductMaster__c, templateLine.QuotationLine__c);
                if (hasExistingLine(existingLineKeysByContractId, groupRecord.contractRecord.Id, lineKey)) {
                    continue;
                }
                lines.add(buildLineFromTemplate(
                    groupRecord.contractRecord,
                    groupRecord.periodRecord.Id,
                    yearMonth,
                    monthStart,
                    templateLine
                ));
                rememberLine(existingLineKeysByContractId, groupRecord.contractRecord.Id, lineKey);
            }
        }
        return lines;
    }

    private static List<ContractLineItem__c> buildLinesFromInvoiceSummary(
        PendingLineGroup groupRecord,
        InvoiceSummary invoiceSummary,
        Map<Id, Set<String>> existingLineKeysByContractId
    ) {
        List<ContractLineItem__c> lines = new List<ContractLineItem__c>();
        for (String yearMonth : buildYearMonthRange(
            groupRecord.periodPlan.periodStartDate,
            groupRecord.periodPlan.monthCount
        )) {
            String lineKey = buildLineKey(yearMonth, null, null);
            if (hasExistingLine(existingLineKeysByContractId, groupRecord.contractRecord.Id, lineKey)) {
                continue;
            }
            Date monthStart = parseYearMonth(yearMonth);
            lines.add(buildLineFromInvoiceSummary(
                groupRecord.contractRecord,
                groupRecord.periodRecord.Id,
                yearMonth,
                monthStart,
                invoiceSummary
            ));
            rememberLine(existingLineKeysByContractId, groupRecord.contractRecord.Id, lineKey);
        }
        return lines;
    }

    private static ContractPeriod__c buildPeriod(
        Contract__c contractRecord,
        PeriodPlan periodPlan,
        LineCreationTiming timing
    ) {
        return new ContractPeriod__c(
            Contract__c = contractRecord.Id,
            ContractUpdate__c = contractRecord.ContractUpdate__c,
            IsInitialPeriod__c = timing == LineCreationTiming.ACTIVATION,
            PeriodStartDate__c = periodPlan.periodStartDate,
            PeriodEndDate__c = periodPlan.periodStartDate.addMonths(periodPlan.monthCount).addDays(-1)
        );
    }

    private static ContractLineItem__c buildLineFromInvoiceSummary(
        Contract__c contractRecord,
        Id contractPeriodId,
        String yearMonth,
        Date monthStart,
        InvoiceSummary invoiceSummary
    ) {
        String sourceName = getContractDisplayName(contractRecord);

        return new ContractLineItem__c(
            Name = sourceName + '_' + yearMonth,
            Account__c = contractRecord.Account__c,
            ContractPeriod__c = contractPeriodId,
            ContractYearMonth__c = yearMonth,
            MasterContract__c = contractRecord.Id,
            Month__c = yearMonth,
            PeopleNumber__c = invoiceSummary == null ? null : invoiceSummary.peopleNumber,
            PeriodStartDate__c = monthStart,
            PeriodEndDate__c = monthStart.addMonths(1).addDays(-1),
            Plan__c = contractRecord.Plan__c,
            RevenueAmount__c = invoiceSummary == null ? null : invoiceSummary.totalAmount,
            Total__c = invoiceSummary == null ? null : invoiceSummary.totalAmount
        );
    }

    private static ContractLineItem__c buildLineFromTemplate(
        Contract__c contractRecord,
        Id contractPeriodId,
        String yearMonth,
        Date monthStart,
        ContractLineItem__c templateLine
    ) {
        Decimal amount = templateLine.RevenueAmount__c == null
            ? templateLine.Total__c
            : templateLine.RevenueAmount__c;
        String sourceName = getContractDisplayName(contractRecord);

        return new ContractLineItem__c(
            Name = sourceName + '_' + yearMonth,
            Account__c = contractRecord.Account__c,
            ARR_Target__c = templateLine.ARR_Target__c,
            ContractPeriod__c = contractPeriodId,
            ContractYearMonth__c = yearMonth,
            InitialFee__c = false,
            MasterContract__c = contractRecord.Id,
            Month__c = yearMonth,
            MRR_Target__c = templateLine.MRR_Target__c,
            PeopleNumber__c = templateLine.PeopleNumber__c,
            PeriodStartDate__c = monthStart,
            PeriodEndDate__c = monthStart.addMonths(1).addDays(-1),
            Plan__c = String.isBlank(templateLine.Plan__c) ? contractRecord.Plan__c : templateLine.Plan__c,
            ProductMaster__c = templateLine.ProductMaster__c,
            QuotationLine__c = templateLine.QuotationLine__c,
            RevenueAmount__c = amount,
            Total__c = amount
        );
    }

    private static List<ContractLineItem__c> collapseTemplateLines(
        List<ContractLineItem__c> templateLines
    ) {
        Map<String, ContractLineItem__c> latestByProduct = new Map<String, ContractLineItem__c>();
        for (ContractLineItem__c templateLine : templateLines) {
            String key = String.valueOf(templateLine.ProductMaster__c) + ':' + String.valueOf(templateLine.QuotationLine__c);
            if (!latestByProduct.containsKey(key)) {
                latestByProduct.put(key, templateLine);
            }
        }
        return latestByProduct.values();
    }

    private static Boolean hasExistingLine(
        Map<Id, Set<String>> existingLineKeysByContractId,
        Id contractId,
        String lineKey
    ) {
        return existingLineKeysByContractId.containsKey(contractId)
            && existingLineKeysByContractId.get(contractId).contains(lineKey);
    }

    private static void rememberLine(
        Map<Id, Set<String>> existingLineKeysByContractId,
        Id contractId,
        String lineKey
    ) {
        if (!existingLineKeysByContractId.containsKey(contractId)) {
            existingLineKeysByContractId.put(contractId, new Set<String>());
        }
        existingLineKeysByContractId.get(contractId).add(lineKey);
    }

    private static String buildPeriodKey(Id contractId, Date periodStartDate) {
        return String.valueOf(contractId) + ':' + String.valueOf(periodStartDate);
    }

    private static String buildLineKey(ContractLineItem__c line) {
        return buildLineKey(line.ContractYearMonth__c, line.ProductMaster__c, line.QuotationLine__c);
    }

    private static String buildLineKey(String yearMonth, Id productMasterId, Id quotationLineId) {
        return yearMonth + ':' + String.valueOf(productMasterId) + ':' + String.valueOf(quotationLineId);
    }

    private static Date parseYearMonth(String yearMonth) {
        List<String> parts = yearMonth.split('/');
        return Date.newInstance(Integer.valueOf(parts[0]), Integer.valueOf(parts[1]), 1);
    }

    private class InvoiceSummary {
        private Decimal peopleNumber;
        private Decimal totalAmount;

        private InvoiceSummary(Decimal peopleNumber, Decimal totalAmount) {
            this.peopleNumber = peopleNumber;
            this.totalAmount = totalAmount;
        }
    }

    private class PeriodPlan {
        private Date periodStartDate;
        private Integer monthCount;

        private PeriodPlan(Date periodStartDate, Integer monthCount) {
            this.periodStartDate = periodStartDate;
            this.monthCount = monthCount;
        }
    }

    private class PendingLineGroup {
        private Contract__c contractRecord;
        private ContractPeriod__c periodRecord;
        private PeriodPlan periodPlan;

        private PendingLineGroup(
            Contract__c contractRecord,
            ContractPeriod__c periodRecord,
            PeriodPlan periodPlan
        ) {
            this.contractRecord = contractRecord;
            this.periodRecord = periodRecord;
            this.periodPlan = periodPlan;
        }
    }

    public class ContractMonthlyLineException extends Exception {
    }
}

public with sharing class ContractRenewalInvoiceBatch
    implements Database.Batchable<SObject>, Database.AllowsCallouts, Schedulable {
    private static final String STATUS_ACTIVATED = 'Activated';
    private static final String UPDATE_MONTHLY = '月';
    private static final String UPDATE_YEARLY = '年';
    private static final String SEND_WAITING = '送付待ち';
    private static final String PAYMENT_WAITING = '決済待ち';
    private static final String PERIOD_STATUS_CREATED = '作成済';
    private static final String FREEE_STATUS_NOT_SYNCED = '未連携';
    private static final String INVOICE_STATUS_BILLED = '請求済';
    private static final Decimal TAX_RATE = 10;

    private Date runDate;

    public ContractRenewalInvoiceBatch() {
        this(Date.today());
    }

    @TestVisible
    private ContractRenewalInvoiceBatch(Date runDate) {
        this.runDate = runDate;
    }

    public void execute(SchedulableContext context) {
        Database.executeBatch(new ContractRenewalInvoiceBatch(), 100);
    }

    public Database.QueryLocator start(Database.BatchableContext context) {
        if (runDate == null || runDate.day() != 11) {
            return Database.getQueryLocator([
                SELECT Id
                FROM Contract__c
                WHERE Id = null
            ]);
        }

        return Database.getQueryLocator([
            SELECT Id,
                   Name,
                   Account__c,
                   Account__r.Freee_Partner_Id__c,
                   ContractName__c,
                   ContractUpdate__c,
                   BillingControlSource__c,
                   Plan__c,
                   RenewalStop__c,
                   StartDate__c,
                   Status__c
            FROM Contract__c
            WHERE Status__c = :STATUS_ACTIVATED
              AND StartDate__c != null
              AND ContractUpdate__c IN (:UPDATE_MONTHLY, :UPDATE_YEARLY)
              AND (BillingControlSource__c = null OR BillingControlSource__c = 'Salesforce')
              AND (RenewalStop__c = false OR RenewalStop__c = null)
        ]);
    }

    public void execute(Database.BatchableContext context, List<Contract__c> scope) {
        List<Contract__c> targetContracts = filterTargets(scope);
        if (targetContracts.isEmpty()) {
            return;
        }

        Map<Id, List<ContractLineItem__c>> templateLinesByContractId =
            getTemplateLinesByContractId(targetContracts);
        Map<Id, Set<Date>> existingPeriodStartDatesByContractId =
            getExistingPeriodStartDatesByContractId(targetContracts);

        List<Id> invoiceIdsForFreeeCreation = new List<Id>();
        for (Contract__c contractRecord : targetContracts) {
            Date periodStartDate = calculateTargetPeriodStartDate(contractRecord);
            if (periodStartDate == null || hasExistingPeriod(
                existingPeriodStartDatesByContractId,
                contractRecord.Id,
                periodStartDate
            )) {
                continue;
            }

            List<ContractLineItem__c> templateLines =
                templateLinesByContractId.get(contractRecord.Id);
            if (templateLines == null || templateLines.isEmpty()) {
                continue;
            }

            Id invoiceId = createRenewalSet(contractRecord, periodStartDate, templateLines);
            if (invoiceId != null) {
                invoiceIdsForFreeeCreation.add(invoiceId);
            }
        }

        if (!invoiceIdsForFreeeCreation.isEmpty() && !Test.isRunningTest()) {
            System.enqueueJob(new FreeeInvoiceCreateQueueable(invoiceIdsForFreeeCreation));
        }
    }

    public void finish(Database.BatchableContext context) {
    }

    private List<Contract__c> filterTargets(List<Contract__c> scope) {
        List<Contract__c> targets = new List<Contract__c>();
        for (Contract__c contractRecord : scope) {
            if (calculateTargetPeriodStartDate(contractRecord) != null) {
                targets.add(contractRecord);
            }
        }
        return targets;
    }

    private Date calculateTargetPeriodStartDate(Contract__c contractRecord) {
        if (contractRecord.ContractUpdate__c == UPDATE_MONTHLY) {
            return firstDayOfMonth(runDate).addMonths(1);
        }

        Date nextMonth = runDate.addMonths(1);
        if (nextMonth.month() != contractRecord.StartDate__c.month()) {
            return null;
        }

        Date targetStartDate = Date.newInstance(
            nextMonth.year(),
            contractRecord.StartDate__c.month(),
            contractRecord.StartDate__c.day()
        );
        return targetStartDate > contractRecord.StartDate__c ? targetStartDate : null;
    }

    private static Map<Id, List<ContractLineItem__c>> getTemplateLinesByContractId(
        List<Contract__c> contracts
    ) {
        Set<Id> contractIds = new Set<Id>();
        for (Contract__c contractRecord : contracts) {
            contractIds.add(contractRecord.Id);
        }

        Map<Id, List<ContractLineItem__c>> linesByContractId =
            new Map<Id, List<ContractLineItem__c>>();
        for (ContractLineItem__c line : [
            SELECT Id,
                   MasterContract__c,
                   ProductMaster__c,
                   ProductMaster__r.Name,
                   ProductMaster__r.Unit__c,
                   QuotationLine__c,
                   RevenueAmount__c,
                   Total__c,
                   PeopleNumber__c,
                   MRR_Target__c,
                   ARR_Target__c
            FROM ContractLineItem__c
            WHERE MasterContract__c IN :contractIds
              AND (InitialFee__c = false OR InitialFee__c = null)
            ORDER BY PeriodStartDate__c DESC, CreatedDate DESC
        ]) {
            if (!linesByContractId.containsKey(line.MasterContract__c)) {
                linesByContractId.put(line.MasterContract__c, new List<ContractLineItem__c>());
            }
            linesByContractId.get(line.MasterContract__c).add(line);
        }
        return linesByContractId;
    }

    private static Map<Id, Set<Date>> getExistingPeriodStartDatesByContractId(
        List<Contract__c> contracts
    ) {
        Set<Id> contractIds = new Set<Id>();
        for (Contract__c contractRecord : contracts) {
            contractIds.add(contractRecord.Id);
        }

        Map<Id, Set<Date>> datesByContractId = new Map<Id, Set<Date>>();
        for (ContractPeriod__c periodRecord : [
            SELECT Contract__c,
                   PeriodStartDate__c
            FROM ContractPeriod__c
            WHERE Contract__c IN :contractIds
        ]) {
            if (!datesByContractId.containsKey(periodRecord.Contract__c)) {
                datesByContractId.put(periodRecord.Contract__c, new Set<Date>());
            }
            datesByContractId.get(periodRecord.Contract__c).add(periodRecord.PeriodStartDate__c);
        }
        return datesByContractId;
    }

    private static Boolean hasExistingPeriod(
        Map<Id, Set<Date>> datesByContractId,
        Id contractId,
        Date periodStartDate
    ) {
        return datesByContractId.containsKey(contractId)
            && datesByContractId.get(contractId).contains(periodStartDate);
    }

    private Id createRenewalSet(
        Contract__c contractRecord,
        Date periodStartDate,
        List<ContractLineItem__c> templateLines
    ) {
        Integer monthCount = contractRecord.ContractUpdate__c == UPDATE_YEARLY ? 12 : 1;
        Date periodEndDate = periodStartDate.addMonths(monthCount).addDays(-1);

        ContractPeriod__c periodRecord = new ContractPeriod__c(
            Contract__c = contractRecord.Id,
            ContractUpdate__c = contractRecord.ContractUpdate__c,
            PeriodStartDate__c = periodStartDate,
            PeriodEndDate__c = periodEndDate,
            IsInitialPeriod__c = false,
            InvoiceCreationStatus__c = PERIOD_STATUS_CREATED,
            FreeeSyncStatus__c = FREEE_STATUS_NOT_SYNCED
        );
        insert periodRecord;

        Date billingDate = previousBusinessDay(Date.newInstance(runDate.year(), runDate.month(), 20));
        Invoice__c invoiceRecord = new Invoice__c(
            Account__c = contractRecord.Account__c,
            Billing_Date__c = billingDate,
            ContractPeriod__c = periodRecord.Id,
            Freee_Account_Item_Picklist__c = 'Sales',
            Freee_Invoice_Status__c = SEND_WAITING,
            Freee_Partner_Id__c = contractRecord.Account__r == null
                ? null
                : contractRecord.Account__r.Freee_Partner_Id__c,
            Freee_Sync_Status__c = 'Processing',
            ParentContract__c = contractRecord.Id,
            PaymentStatus__c = PAYMENT_WAITING,
            Payment_Date__c = calculatePaymentDueDate(billingDate),
            Subject__c = buildInvoiceSubject(contractRecord, periodStartDate, periodEndDate),
            TargetPeriodStartDate__c = periodStartDate,
            TargetPeriodEndDate__c = periodEndDate
        );
        insert invoiceRecord;

        insert buildInvoiceLines(invoiceRecord.Id, contractRecord.ContractUpdate__c, templateLines);
        insert buildContractLines(
            contractRecord,
            periodRecord.Id,
            invoiceRecord.Id,
            periodStartDate,
            monthCount,
            templateLines
        );

        periodRecord.RelatedInvoice__c = invoiceRecord.Id;
        update periodRecord;
        return invoiceRecord.Id;
    }

    private static List<InvoiceLine__c> buildInvoiceLines(
        Id invoiceId,
        String contractUpdate,
        List<ContractLineItem__c> templateLines
    ) {
        List<InvoiceLine__c> invoiceLines = new List<InvoiceLine__c>();
        if (contractUpdate == UPDATE_YEARLY) {
            Decimal amount = 0;
            List<String> productNames = new List<String>();
            for (ContractLineItem__c templateLine : collapseTemplateLines(templateLines)) {
                amount += getRevenueAmount(templateLine) * 12;
                productNames.add(getTemplateLineName(templateLine));
            }
            Decimal taxAmount = calculateTax(amount);
            invoiceLines.add(new InvoiceLine__c(
                AmountWithTax__c = amount + taxAmount,
                Description__c = buildAnnualLineName(productNames),
                DiscountedUnitPrice__c = amount,
                Invoice__c = invoiceId,
                LineType__c = '年間利用料',
                Quantity__c = 1,
                TaxAmount__c = taxAmount,
                Tax_Rate__c = TAX_RATE,
                Unit__c = '式',
                Unit_Price__c = amount
            ));
            return invoiceLines;
        }

        for (ContractLineItem__c templateLine : collapseTemplateLines(templateLines)) {
            Decimal amount = getRevenueAmount(templateLine);
            Decimal taxAmount = calculateTax(amount);
            invoiceLines.add(new InvoiceLine__c(
                AmountWithTax__c = amount + taxAmount,
                Description__c = getTemplateLineName(templateLine),
                DiscountedUnitPrice__c = amount,
                Invoice__c = invoiceId,
                LineType__c = '継続費用',
                ProductMaster__c = templateLine.ProductMaster__c,
                Quantity__c = nullToOne(templateLine.PeopleNumber__c),
                TaxAmount__c = taxAmount,
                Tax_Rate__c = TAX_RATE,
                Unit__c = getTemplateLineUnit(templateLine),
                Unit_Price__c = amount
            ));
        }
        return invoiceLines;
    }

    private static List<ContractLineItem__c> buildContractLines(
        Contract__c contractRecord,
        Id periodId,
        Id invoiceId,
        Date periodStartDate,
        Integer monthCount,
        List<ContractLineItem__c> templateLines
    ) {
        List<ContractLineItem__c> lines = new List<ContractLineItem__c>();
        List<ContractLineItem__c> collapsedTemplateLines = collapseTemplateLines(templateLines);
        for (Integer monthIndex = 0; monthIndex < monthCount; monthIndex++) {
            Date monthStart = firstDayOfMonth(periodStartDate).addMonths(monthIndex);
            String yearMonth = formatYearMonth(monthStart);
            for (ContractLineItem__c templateLine : collapsedTemplateLines) {
                Decimal amount = getRevenueAmount(templateLine);
                lines.add(new ContractLineItem__c(
                    Account__c = contractRecord.Account__c,
                    ARR_Target__c = templateLine.ARR_Target__c,
                    ContractPeriod__c = periodId,
                    ContractYearMonth__c = yearMonth,
                    InitialFee__c = false,
                    InvoiceStatus__c = INVOICE_STATUS_BILLED,
                    MasterContract__c = contractRecord.Id,
                    Month__c = yearMonth,
                    MRR_Target__c = templateLine.MRR_Target__c,
                    PeopleNumber__c = templateLine.PeopleNumber__c,
                    PeriodStartDate__c = monthStart,
                    PeriodEndDate__c = monthStart.addMonths(1).addDays(-1),
                    Plan__c = contractRecord.Plan__c,
                    ProductMaster__c = templateLine.ProductMaster__c,
                    QuotationLine__c = templateLine.QuotationLine__c,
                    RelatedInvoice__c = invoiceId,
                    RevenueAmount__c = amount,
                    Total__c = amount
                ));
            }
        }
        return lines;
    }

    private static List<ContractLineItem__c> collapseTemplateLines(
        List<ContractLineItem__c> templateLines
    ) {
        Map<String, ContractLineItem__c> latestByProduct = new Map<String, ContractLineItem__c>();
        for (ContractLineItem__c templateLine : templateLines) {
            String key = templateLine.ProductMaster__c == null
                ? String.valueOf(templateLine.QuotationLine__c)
                : String.valueOf(templateLine.ProductMaster__c);
            if (!latestByProduct.containsKey(key)) {
                latestByProduct.put(key, templateLine);
            }
        }
        return latestByProduct.values();
    }

    private static String buildInvoiceSubject(
        Contract__c contractRecord,
        Date periodStartDate,
        Date periodEndDate
    ) {
        return getContractDisplayName(contractRecord)
            + ' '
            + formatYearMonth(periodStartDate)
            + '-'
            + formatYearMonth(periodEndDate);
    }

    private static String buildAnnualLineName(List<String> productNames) {
        List<String> names = new List<String>();
        Set<String> seen = new Set<String>();
        for (String productName : productNames) {
            if (String.isBlank(productName) || seen.contains(productName)) {
                continue;
            }
            names.add(productName);
            seen.add(productName);
        }
        return names.isEmpty() ? '年間利用料' : String.join(names, '・') + ' 年間利用料';
    }

    private static String getTemplateLineName(ContractLineItem__c templateLine) {
        if (templateLine.ProductMaster__r != null && !String.isBlank(templateLine.ProductMaster__r.Name)) {
            return templateLine.ProductMaster__r.Name;
        }
        return '利用料';
    }

    private static String getTemplateLineUnit(ContractLineItem__c templateLine) {
        if (templateLine.ProductMaster__r != null && !String.isBlank(templateLine.ProductMaster__r.Unit__c)) {
            return templateLine.ProductMaster__r.Unit__c;
        }
        return null;
    }

    private static Decimal getRevenueAmount(ContractLineItem__c templateLine) {
        return templateLine.RevenueAmount__c == null
            ? nullToZero(templateLine.Total__c)
            : templateLine.RevenueAmount__c;
    }

    private static String getContractDisplayName(Contract__c contractRecord) {
        return String.isBlank(contractRecord.ContractName__c)
            ? contractRecord.Name
            : contractRecord.ContractName__c;
    }

    private static Date calculatePaymentDueDate(Date billingDate) {
        Date nextMonth = billingDate.addMonths(1);
        return Date.newInstance(nextMonth.year(), nextMonth.month(), 1)
            .addMonths(1)
            .addDays(-1);
    }

    private static Date previousBusinessDay(Date sourceDate) {
        Date adjustedDate = sourceDate;
        while (isWeekend(adjustedDate)) {
            adjustedDate = adjustedDate.addDays(-1);
        }
        return adjustedDate;
    }

    private static Boolean isWeekend(Date sourceDate) {
        Integer dayOffset = sourceDate.toStartOfWeek().daysBetween(sourceDate);
        return dayOffset == 0 || dayOffset == 6;
    }

    private static Date firstDayOfMonth(Date sourceDate) {
        return Date.newInstance(sourceDate.year(), sourceDate.month(), 1);
    }

    private static String formatYearMonth(Date sourceDate) {
        return String.valueOf(sourceDate.year()) + '/' + String.valueOf(sourceDate.month()).leftPad(2, '0');
    }

    private static Decimal calculateTax(Decimal amount) {
        return (nullToZero(amount) * TAX_RATE / 100).round(System.RoundingMode.CEILING);
    }

    private static Decimal nullToZero(Decimal sourceValue) {
        return sourceValue == null ? 0 : sourceValue;
    }

    private static Decimal nullToOne(Decimal sourceValue) {
        return sourceValue == null ? 1 : sourceValue;
    }
}

public with sharing class FreeeInvoiceContractProvisioningService {
    private static final String STATUS_ACTIVATED = 'Activated';
    private static final String UPDATE_MONTHLY = '月';
    private static final String UPDATE_YEARLY = '年';
    private static final String CYCLE_MONTHLY = 'Monthly';
    private static final String CYCLE_YEARLY = 'Yearly';
    private static final String CYCLE_ONE_TIME = 'OneTime';
    private static final String NATURE_RECURRING = 'Recurring';
    private static final String NATURE_ONE_TIME = 'OneTime';
    private static final String BILLING_SOURCE_FREEE = 'Freee';
    private static final String CREATION_SOURCE_FREEE = 'FreeeImport';

    public static void provisionAll() {
        List<Mig_FreeeInvoiceWork__c> works = [
            SELECT Id,
                   FreeePartnerId__c,
                   Subject__c,
                   BillingDate__c,
                   TargetPeriodStartDate__c,
                   TargetPeriodEndDate__c,
                   ResolvedAccount__c,
                   ResolvedContract__c,
                   ResolvedContractPeriod__c,
                   ResolutionAction__c,
                   ProvisioningMessage__c,
                   ImportStatus__c,
                   (SELECT Id,
                           ConfirmedProductMaster__c,
                           Quantity__c,
                           LineAmount__c,
                           ImportStatus__c
                    FROM InvoiceLineWorks__r)
            FROM Mig_FreeeInvoiceWork__c
            WHERE ImportStatus__c IN :new List<String>{
                Mig_FreeeInvoiceWorkService.STATUS_FETCHED,
                Mig_FreeeInvoiceWorkService.STATUS_NEEDS_REVIEW,
                Mig_FreeeInvoiceWorkService.STATUS_READY
            }
              AND ResolvedAccount__c != null
        ];
        if (works.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        Set<Id> productIds = new Set<Id>();
        Set<Id> knownContractIds = new Set<Id>();
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            accountIds.add(workRecord.ResolvedAccount__c);
            if (workRecord.ResolvedContract__c != null) {
                knownContractIds.add(workRecord.ResolvedContract__c);
            }
            for (Mig_FreeeInvoiceLineWork__c line : activeLines(workRecord)) {
                if (line.ConfirmedProductMaster__c != null) {
                    productIds.add(line.ConfirmedProductMaster__c);
                }
            }
        }

        Map<Id, Account> accountsById = new Map<Id, Account>([
            SELECT Id, Name
            FROM Account
            WHERE Id IN :accountIds
        ]);
        Map<Id, ProductMaster__c> productsById = productIds.isEmpty()
            ? new Map<Id, ProductMaster__c>()
            : new Map<Id, ProductMaster__c>([
                SELECT Id,
                       Name,
                       AnnualMonthlyPrice__c,
                       ARR_Target__c,
                       MRR_Target__c
                FROM ProductMaster__c
                WHERE Id IN :productIds
            ]);
        Set<Id> ambiguousExistingContractWorkIds =
            resolveExistingContractsByProduct(
                works,
                accountIds,
                productIds,
                knownContractIds
            );

        List<FreeeInvoiceContractRule__c> rules = [
            SELECT Id,
                   Name,
                   Account__c,
                   FreeePartnerId__c,
                   ProductMaster__c,
                   SubjectKeyword__c,
                   BillingCycle__c,
                   AutoCreateAllowed__c,
                   IsActive__c,
                   Contract__c,
                   ContractName__c,
                   StartDate__c,
                   EndDate__c
            FROM FreeeInvoiceContractRule__c
            WHERE IsActive__c = true
              AND (Account__c = null OR Account__c IN :accountIds)
        ];
        Map<Id, List<FreeeInvoiceContractRule__c>> rulesByAccount =
            new Map<Id, List<FreeeInvoiceContractRule__c>>();
        List<FreeeInvoiceContractRule__c> commonRules =
            new List<FreeeInvoiceContractRule__c>();
        groupRules(rules, rulesByAccount, commonRules, knownContractIds);

        Map<Id, FreeeInvoiceContractRule__c> selectedRuleByWorkId =
            new Map<Id, FreeeInvoiceContractRule__c>();
        Map<String, List<Mig_FreeeInvoiceWork__c>> worksByRuleAndAccount =
            new Map<String, List<Mig_FreeeInvoiceWork__c>>();

        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            if (workRecord.ResolvedContract__c != null) {
                workRecord.ResolutionAction__c = 'ExistingContract';
                workRecord.ProvisioningMessage__c = '既存の契約管理を使用します。';
                continue;
            }
            if (ambiguousExistingContractWorkIds.contains(workRecord.Id)) {
                continue;
            }
            if (!hasConfirmedProducts(workRecord)) {
                workRecord.ResolutionAction__c = 'NeedsReview';
                workRecord.ProvisioningMessage__c =
                    '商品マスタが確定していないため、契約管理を自動作成しません。';
                continue;
            }

            List<FreeeInvoiceContractRule__c> matches = matchingRules(
                workRecord,
                rulesByAccount.get(workRecord.ResolvedAccount__c),
                commonRules
            );
            if (matches.size() != 1) {
                workRecord.ResolutionAction__c = 'NeedsReview';
                workRecord.ProvisioningMessage__c = matches.isEmpty()
                    ? '承認済みのFreee請求契約ルールがないため、契約管理を自動作成しません。'
                    : '一致するFreee請求契約ルールが複数あるため、自動確定しません。';
                continue;
            }

            FreeeInvoiceContractRule__c selectedRule = matches[0];
            selectedRuleByWorkId.put(workRecord.Id, selectedRule);
            if (selectedRule.Contract__c != null) {
                workRecord.ResolvedContract__c = selectedRule.Contract__c;
                workRecord.ResolutionAction__c = 'ExistingContract';
                workRecord.ProvisioningMessage__c =
                    'Freee請求契約ルールに設定された契約管理を使用します。';
            } else if (selectedRule.AutoCreateAllowed__c) {
                String provisioningKey =
                    selectedRule.Id + ':' + workRecord.ResolvedAccount__c;
                if (!worksByRuleAndAccount.containsKey(provisioningKey)) {
                    worksByRuleAndAccount.put(
                        provisioningKey,
                        new List<Mig_FreeeInvoiceWork__c>()
                    );
                }
                worksByRuleAndAccount.get(provisioningKey).add(workRecord);
            } else {
                workRecord.ResolutionAction__c = 'NeedsReview';
                workRecord.ProvisioningMessage__c =
                    'Freee請求契約ルールで契約管理の自動作成が許可されていません。';
            }
        }

        createContractsForRules(
            worksByRuleAndAccount,
            selectedRuleByWorkId,
            accountsById,
            productsById,
            knownContractIds
        );

        Map<Id, Contract__c> contractsById = knownContractIds.isEmpty()
            ? new Map<Id, Contract__c>()
            : new Map<Id, Contract__c>([
                SELECT Id,
                       Account__c,
                       ContractName__c,
                       ContractUpdate__c,
                       ContractNature__c,
                       BillingControlSource__c,
                       StartDate__c,
                       EndDate__c
                FROM Contract__c
                WHERE Id IN :knownContractIds
            ]);

        provisionPeriodsAndMonthlyLines(works, contractsById, productsById);
        update works;
    }

    private static Set<Id> resolveExistingContractsByProduct(
        List<Mig_FreeeInvoiceWork__c> works,
        Set<Id> accountIds,
        Set<Id> productIds,
        Set<Id> knownContractIds
    ) {
        Set<Id> ambiguousWorkIds = new Set<Id>();
        if (accountIds.isEmpty() || productIds.isEmpty()) {
            return ambiguousWorkIds;
        }

        Map<Id, Contract__c> contractById = new Map<Id, Contract__c>();
        Map<Id, Set<Id>> productIdsByContract = new Map<Id, Set<Id>>();
        Map<Id, List<Contract__c>> contractsByAccount =
            new Map<Id, List<Contract__c>>();
        for (ContractLineItem__c contractLine : [
            SELECT MasterContract__c,
                   ProductMaster__c,
                   MasterContract__r.Id,
                   MasterContract__r.Account__c,
                   MasterContract__r.StartDate__c,
                   MasterContract__r.EndDate__c,
                   MasterContract__r.Status__c
            FROM ContractLineItem__c
            WHERE MasterContract__r.Account__c IN :accountIds
              AND MasterContract__r.Status__c = :STATUS_ACTIVATED
              AND ProductMaster__c IN :productIds
        ]) {
            Id contractId = contractLine.MasterContract__c;
            if (!contractById.containsKey(contractId)) {
                Contract__c contractRecord = contractLine.MasterContract__r;
                contractById.put(contractId, contractRecord);
                Id accountId = contractRecord.Account__c;
                if (!contractsByAccount.containsKey(accountId)) {
                    contractsByAccount.put(accountId, new List<Contract__c>());
                }
                contractsByAccount.get(accountId).add(contractRecord);
            }
            if (!productIdsByContract.containsKey(contractId)) {
                productIdsByContract.put(contractId, new Set<Id>());
            }
            productIdsByContract.get(contractId).add(contractLine.ProductMaster__c);
        }

        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            if (workRecord.ResolvedContract__c != null) {
                continue;
            }
            Set<Id> requiredProductIds = confirmedProductIds(workRecord);
            if (requiredProductIds.isEmpty()) {
                continue;
            }
            List<Contract__c> candidates = new List<Contract__c>();
            List<Contract__c> accountContracts =
                contractsByAccount.get(workRecord.ResolvedAccount__c);
            if (accountContracts != null) {
                for (Contract__c contractRecord : accountContracts) {
                    Set<Id> contractProductIds =
                        productIdsByContract.get(contractRecord.Id);
                    if (containsAllProducts(contractProductIds, requiredProductIds)
                        && contractContainsTarget(contractRecord, workRecord)) {
                        candidates.add(contractRecord);
                    }
                }
            }
            if (candidates.size() == 1) {
                workRecord.ResolvedContract__c = candidates[0].Id;
                workRecord.ResolutionAction__c = 'ExistingContract';
                workRecord.ProvisioningMessage__c =
                    '取引先・商品・対象日に一致する既存の契約管理を使用します。';
                knownContractIds.add(candidates[0].Id);
            } else if (candidates.size() > 1) {
                workRecord.ResolutionAction__c = 'NeedsReview';
                workRecord.ProvisioningMessage__c =
                    '取引先・商品・対象日に一致する既存契約が複数あるため、新しい契約を自動作成しません。';
                ambiguousWorkIds.add(workRecord.Id);
            }
        }
        return ambiguousWorkIds;
    }

    private static Boolean containsAllProducts(
        Set<Id> availableProductIds,
        Set<Id> requiredProductIds
    ) {
        if (availableProductIds == null) {
            return false;
        }
        for (Id productId : requiredProductIds) {
            if (!availableProductIds.contains(productId)) {
                return false;
            }
        }
        return true;
    }

    private static void groupRules(
        List<FreeeInvoiceContractRule__c> rules,
        Map<Id, List<FreeeInvoiceContractRule__c>> rulesByAccount,
        List<FreeeInvoiceContractRule__c> commonRules,
        Set<Id> knownContractIds
    ) {
        for (FreeeInvoiceContractRule__c rule : rules) {
            if (rule.Account__c == null) {
                commonRules.add(rule);
            } else {
                if (!rulesByAccount.containsKey(rule.Account__c)) {
                    rulesByAccount.put(
                        rule.Account__c,
                        new List<FreeeInvoiceContractRule__c>()
                    );
                }
                rulesByAccount.get(rule.Account__c).add(rule);
            }
            if (rule.Contract__c != null) {
                knownContractIds.add(rule.Contract__c);
            }
        }
    }

    private static List<FreeeInvoiceContractRule__c> matchingRules(
        Mig_FreeeInvoiceWork__c workRecord,
        List<FreeeInvoiceContractRule__c> accountRules,
        List<FreeeInvoiceContractRule__c> commonRules
    ) {
        List<FreeeInvoiceContractRule__c> accountMatches =
            matchingRulesAtScope(workRecord, accountRules);
        if (!accountMatches.isEmpty()) {
            return accountMatches;
        }
        return matchingRulesAtScope(workRecord, commonRules);
    }

    private static List<FreeeInvoiceContractRule__c> matchingRulesAtScope(
        Mig_FreeeInvoiceWork__c workRecord,
        List<FreeeInvoiceContractRule__c> candidateRules
    ) {
        List<FreeeInvoiceContractRule__c> matches =
            new List<FreeeInvoiceContractRule__c>();
        if (candidateRules == null || candidateRules.isEmpty()) {
            return matches;
        }
        Set<Id> lineProductIds = confirmedProductIds(workRecord);
        String normalizedSubject = Mig_FreeeInvoiceWorkService.normalize(workRecord.Subject__c);
        for (FreeeInvoiceContractRule__c rule : candidateRules) {
            if (!String.isBlank(rule.FreeePartnerId__c)
                && rule.FreeePartnerId__c != workRecord.FreeePartnerId__c) {
                continue;
            }
            if (rule.ProductMaster__c != null
                && !lineProductIds.contains(rule.ProductMaster__c)) {
                continue;
            }
            if (!String.isBlank(rule.SubjectKeyword__c)
                && (
                    String.isBlank(normalizedSubject)
                    || !normalizedSubject.contains(
                        Mig_FreeeInvoiceWorkService.normalize(rule.SubjectKeyword__c)
                    )
                )) {
                continue;
            }
            matches.add(rule);
        }
        return matches;
    }

    private static void createContractsForRules(
        Map<String, List<Mig_FreeeInvoiceWork__c>> worksByRuleAndAccount,
        Map<Id, FreeeInvoiceContractRule__c> selectedRuleByWorkId,
        Map<Id, Account> accountsById,
        Map<Id, ProductMaster__c> productsById,
        Set<Id> knownContractIds
    ) {
        if (worksByRuleAndAccount.isEmpty()) {
            return;
        }

        List<Contract__c> contractsToInsert = new List<Contract__c>();
        List<String> provisioningKeysInInsertOrder = new List<String>();
        for (String provisioningKey : worksByRuleAndAccount.keySet()) {
            List<Mig_FreeeInvoiceWork__c> ruleWorks =
                worksByRuleAndAccount.get(provisioningKey);
            Mig_FreeeInvoiceWork__c firstWork = ruleWorks[0];
            FreeeInvoiceContractRule__c rule =
                selectedRuleByWorkId.get(firstWork.Id);
            Id accountId = firstWork.ResolvedAccount__c;
            Boolean oneTime = rule.BillingCycle__c == CYCLE_ONE_TIME;
            String updateCycle = rule.BillingCycle__c == CYCLE_YEARLY
                ? UPDATE_YEARLY
                : UPDATE_MONTHLY;
            Date earliestStart = earliestTargetStart(ruleWorks, updateCycle);
            if (earliestStart == null) {
                for (Mig_FreeeInvoiceWork__c workRecord : ruleWorks) {
                    workRecord.ResolutionAction__c = 'NeedsReview';
                    workRecord.ProvisioningMessage__c =
                        '請求対象期間を特定できないため、契約管理を自動作成しません。';
                }
                continue;
            }
            Account accountRecord = accountsById.get(accountId);
            ProductMaster__c productRecord = productsById.get(rule.ProductMaster__c);
            String contractName = String.isBlank(rule.ContractName__c)
                ? buildContractName(accountRecord, productRecord, oneTime)
                : rule.ContractName__c;

            contractsToInsert.add(new Contract__c(
                Account__c = accountId,
                AutoCreatedFromFreee__c = true,
                BillingControlSource__c = BILLING_SOURCE_FREEE,
                ContractName__c = contractName,
                ContractNature__c = oneTime ? NATURE_ONE_TIME : NATURE_RECURRING,
                ContractUpdate__c = updateCycle,
                CreationSource__c = CREATION_SOURCE_FREEE,
                EndDate__c = oneTime
                    ? effectivePeriodEnd(ruleWorks[0], updateCycle, oneTime)
                    : rule.EndDate__c,
                Payment__c = 'Invoice',
                RenewalStop__c = true,
                StartDate__c = rule.StartDate__c == null ? earliestStart : rule.StartDate__c,
                Status__c = STATUS_ACTIVATED
            ));
            provisioningKeysInInsertOrder.add(provisioningKey);
        }

        if (contractsToInsert.isEmpty()) {
            return;
        }
        insert contractsToInsert;

        List<FreeeInvoiceContractRule__c> rulesToUpdate =
            new List<FreeeInvoiceContractRule__c>();
        for (Integer index = 0; index < contractsToInsert.size(); index++) {
            String provisioningKey = provisioningKeysInInsertOrder[index];
            List<Mig_FreeeInvoiceWork__c> ruleWorks =
                worksByRuleAndAccount.get(provisioningKey);
            FreeeInvoiceContractRule__c rule =
                selectedRuleByWorkId.get(ruleWorks[0].Id);
            Id contractId = contractsToInsert[index].Id;
            knownContractIds.add(contractId);
            if (rule.Account__c != null && rule.Contract__c == null) {
                rulesToUpdate.add(new FreeeInvoiceContractRule__c(
                    Id = rule.Id,
                    Contract__c = contractId
                ));
            }
            for (Mig_FreeeInvoiceWork__c workRecord : ruleWorks) {
                workRecord.ResolvedContract__c = contractId;
                Boolean oneTime =
                    rule.BillingCycle__c == CYCLE_ONE_TIME;
                workRecord.ResolutionAction__c = oneTime
                    ? 'OneTimeContractProvisioned'
                    : 'ContractProvisioned';
                workRecord.ProvisioningMessage__c = oneTime
                    ? '更新停止済み・MRR対象外の単発契約を自動作成しました。'
                    : '承認済みルールからFreee管理の継続契約を自動作成しました。';
            }
        }
        if (!rulesToUpdate.isEmpty()) {
            update rulesToUpdate;
        }
    }

    private static void provisionPeriodsAndMonthlyLines(
        List<Mig_FreeeInvoiceWork__c> works,
        Map<Id, Contract__c> contractsById,
        Map<Id, ProductMaster__c> productsById
    ) {
        Set<Id> contractIds = new Set<Id>();
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            if (workRecord.ResolvedContract__c != null) {
                contractIds.add(workRecord.ResolvedContract__c);
            }
        }
        if (contractIds.isEmpty()) {
            return;
        }

        if (contractsById.size() < contractIds.size()) {
            contractsById.putAll(new Map<Id, Contract__c>([
                SELECT Id,
                       Account__c,
                       ContractName__c,
                       ContractUpdate__c,
                       ContractNature__c,
                       BillingControlSource__c,
                       StartDate__c,
                       EndDate__c
                FROM Contract__c
                WHERE Id IN :contractIds
            ]));
        }

        Map<String, ContractPeriod__c> periodByKey =
            new Map<String, ContractPeriod__c>();
        Map<Id, List<ContractPeriod__c>> periodsByContractId =
            new Map<Id, List<ContractPeriod__c>>();
        for (ContractPeriod__c periodRecord : [
            SELECT Id,
                   Contract__c,
                   PeriodStartDate__c,
                   PeriodEndDate__c
            FROM ContractPeriod__c
            WHERE Contract__c IN :contractIds
        ]) {
            periodByKey.put(
                periodKey(
                    periodRecord.Contract__c,
                    periodRecord.PeriodStartDate__c,
                    periodRecord.PeriodEndDate__c
                ),
                periodRecord
            );
            if (!periodsByContractId.containsKey(periodRecord.Contract__c)) {
                periodsByContractId.put(
                    periodRecord.Contract__c,
                    new List<ContractPeriod__c>()
                );
            }
            periodsByContractId.get(periodRecord.Contract__c)
                .add(periodRecord);
        }

        List<ContractPeriod__c> periodsToInsert = new List<ContractPeriod__c>();
        Map<String, List<Mig_FreeeInvoiceWork__c>> worksByPeriodKey =
            new Map<String, List<Mig_FreeeInvoiceWork__c>>();
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            if (workRecord.ResolvedContract__c == null
                || workRecord.ResolvedContractPeriod__c != null
                || !hasConfirmedProducts(workRecord)) {
                continue;
            }
            Contract__c contractRecord = contractsById.get(workRecord.ResolvedContract__c);
            if (contractRecord == null || !contractContainsTarget(contractRecord, workRecord)) {
                workRecord.ResolutionAction__c = 'NeedsReview';
                workRecord.ProvisioningMessage__c =
                    '請求対象日が契約期間外のため、契約期間を自動作成しません。';
                continue;
            }

            Boolean oneTime = contractRecord.ContractNature__c == NATURE_ONE_TIME;
            Date periodStart = effectivePeriodStart(
                workRecord,
                contractRecord.ContractUpdate__c
            );
            Date periodEnd = effectivePeriodEnd(
                workRecord,
                contractRecord.ContractUpdate__c,
                oneTime
            );
            if (periodStart == null || periodEnd == null) {
                workRecord.ResolutionAction__c = 'NeedsReview';
                workRecord.ProvisioningMessage__c =
                    '請求対象期間を特定できないため、契約期間を自動作成しません。';
                continue;
            }

            String key = periodKey(contractRecord.Id, periodStart, periodEnd);
            if (!periodByKey.containsKey(key)
                && hasOverlappingPeriod(
                    periodsByContractId.get(contractRecord.Id),
                    periodStart,
                    periodEnd
                )) {
                workRecord.ResolutionAction__c = 'NeedsReview';
                workRecord.ProvisioningMessage__c =
                    '既存の契約期間と重複するため、契約期間を自動作成しません。対象期間を確認してください。';
                continue;
            }
            if (!worksByPeriodKey.containsKey(key)) {
                worksByPeriodKey.put(key, new List<Mig_FreeeInvoiceWork__c>());
            }
            worksByPeriodKey.get(key).add(workRecord);
            if (!periodByKey.containsKey(key)) {
                ContractPeriod__c newPeriod = new ContractPeriod__c(
                    Contract__c = contractRecord.Id,
                    ContractUpdate__c = contractRecord.ContractUpdate__c,
                    FreeeSyncStatus__c = '連携済',
                    InvoiceCreationStatus__c = '作成済',
                    IsInitialPeriod__c = false,
                    PeriodStartDate__c = periodStart,
                    PeriodEndDate__c = periodEnd
                );
                periodsToInsert.add(newPeriod);
                periodByKey.put(key, newPeriod);
                if (!periodsByContractId.containsKey(contractRecord.Id)) {
                    periodsByContractId.put(
                        contractRecord.Id,
                        new List<ContractPeriod__c>()
                    );
                }
                periodsByContractId.get(contractRecord.Id).add(newPeriod);
            }
        }

        if (!periodsToInsert.isEmpty()) {
            insert periodsToInsert;
        }

        for (String key : worksByPeriodKey.keySet()) {
            ContractPeriod__c periodRecord = periodByKey.get(key);
            for (Mig_FreeeInvoiceWork__c workRecord : worksByPeriodKey.get(key)) {
                workRecord.ResolvedContractPeriod__c = periodRecord.Id;
                if (workRecord.ResolutionAction__c == 'ExistingContract') {
                    workRecord.ResolutionAction__c = 'PeriodProvisioned';
                    workRecord.ProvisioningMessage__c =
                        '既存契約に不足していた契約期間・契約月次明細を補完しました。';
                }
            }
        }

        ensureMonthlyLines(works, contractsById, productsById);
    }

    private static void ensureMonthlyLines(
        List<Mig_FreeeInvoiceWork__c> works,
        Map<Id, Contract__c> contractsById,
        Map<Id, ProductMaster__c> productsById
    ) {
        Set<Id> periodIds = new Set<Id>();
        Set<Id> requiredProductIds = new Set<Id>();
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            if (workRecord.ResolvedContractPeriod__c == null) {
                continue;
            }
            periodIds.add(workRecord.ResolvedContractPeriod__c);
            requiredProductIds.addAll(confirmedProductIds(workRecord));
        }
        if (periodIds.isEmpty() || requiredProductIds.isEmpty()) {
            return;
        }

        Set<String> existingKeys = new Set<String>();
        for (ContractLineItem__c line : [
            SELECT Id, ContractPeriod__c, ProductMaster__c
            FROM ContractLineItem__c
            WHERE ContractPeriod__c IN :periodIds
              AND ProductMaster__c IN :requiredProductIds
        ]) {
            existingKeys.add(line.ContractPeriod__c + ':' + line.ProductMaster__c);
        }

        Map<String, Decimal> netRevenueByKey = new Map<String, Decimal>();
        Map<String, Decimal> quantityByKey = new Map<String, Decimal>();
        Map<String, Mig_FreeeInvoiceWork__c> sourceWorkByKey =
            new Map<String, Mig_FreeeInvoiceWork__c>();
        Map<String, Id> productIdByKey = new Map<String, Id>();
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            if (workRecord.ResolvedContractPeriod__c == null) {
                continue;
            }
            Contract__c contractRecord = contractsById.get(workRecord.ResolvedContract__c);
            Boolean oneTime = contractRecord != null
                && contractRecord.ContractNature__c == NATURE_ONE_TIME;
            for (Mig_FreeeInvoiceLineWork__c lineWork : activeLines(workRecord)) {
                if (lineWork.ConfirmedProductMaster__c == null) {
                    continue;
                }
                String key = workRecord.ResolvedContractPeriod__c
                    + ':'
                    + lineWork.ConfirmedProductMaster__c;
                if (existingKeys.contains(key)) {
                    continue;
                }
                Decimal quantity = lineWork.Quantity__c == null
                    || lineWork.Quantity__c == 0
                    ? 1
                    : lineWork.Quantity__c;
                Decimal currentRevenue = netRevenueByKey.containsKey(key)
                    ? netRevenueByKey.get(key)
                    : 0;
                netRevenueByKey.put(
                    key,
                    currentRevenue
                        + (lineWork.LineAmount__c == null
                            ? 0
                            : lineWork.LineAmount__c)
                );
                if (lineWork.LineAmount__c == null
                    || lineWork.LineAmount__c >= 0) {
                    Decimal currentQuantity = quantityByKey.get(key);
                    if (currentQuantity == null || quantity > currentQuantity) {
                        quantityByKey.put(key, quantity);
                    }
                }
                if (!sourceWorkByKey.containsKey(key)) {
                    sourceWorkByKey.put(key, workRecord);
                    productIdByKey.put(
                        key,
                        lineWork.ConfirmedProductMaster__c
                    );
                }
            }
        }

        List<ContractLineItem__c> linesToInsert =
            new List<ContractLineItem__c>();
        for (String key : netRevenueByKey.keySet()) {
            Mig_FreeeInvoiceWork__c workRecord = sourceWorkByKey.get(key);
            Contract__c contractRecord =
                contractsById.get(workRecord.ResolvedContract__c);
            Boolean oneTime = contractRecord != null
                && contractRecord.ContractNature__c == NATURE_ONE_TIME;
            Id productId = productIdByKey.get(key);
            ProductMaster__c product = productsById.get(productId);
            Decimal quantity = quantityByKey.get(key);
            if (quantity == null || quantity == 0) {
                quantity = 1;
            }
            Decimal monthlyRevenue = netRevenueByKey.get(key);
            if (!oneTime
                && contractRecord != null
                && contractRecord.ContractUpdate__c == UPDATE_YEARLY) {
                monthlyRevenue = monthlyRevenue / 12;
            }
            linesToInsert.add(new ContractLineItem__c(
                    Account__c = workRecord.ResolvedAccount__c,
                    ARR_Target__c = !oneTime && product != null && product.ARR_Target__c,
                    ContractPeriod__c = workRecord.ResolvedContractPeriod__c,
                    InitialFee__c = oneTime,
                    MasterContract__c = workRecord.ResolvedContract__c,
                    MRR_Target__c = !oneTime && product != null && product.MRR_Target__c,
                    PeopleNumber__c = quantity,
                    PeriodStartDate__c = effectivePeriodStart(
                        workRecord,
                        contractRecord == null ? UPDATE_MONTHLY : contractRecord.ContractUpdate__c
                    ),
                    PeriodEndDate__c = effectivePeriodEnd(
                        workRecord,
                        contractRecord == null ? UPDATE_MONTHLY : contractRecord.ContractUpdate__c,
                        oneTime
                    ),
                    ProductMaster__c = productId,
                    RevenueAmount__c = monthlyRevenue,
                    Total__c = monthlyRevenue
                ));
        }
        if (!linesToInsert.isEmpty()) {
            insert linesToInsert;
        }
    }

    private static Boolean hasOverlappingPeriod(
        List<ContractPeriod__c> periods,
        Date startDate,
        Date endDate
    ) {
        if (periods == null || startDate == null || endDate == null) {
            return false;
        }
        for (ContractPeriod__c periodRecord : periods) {
            if (periodRecord.PeriodStartDate__c == null
                || periodRecord.PeriodEndDate__c == null) {
                continue;
            }
            if (periodRecord.PeriodStartDate__c <= endDate
                && periodRecord.PeriodEndDate__c >= startDate) {
                return true;
            }
        }
        return false;
    }

    private static Boolean hasConfirmedProducts(Mig_FreeeInvoiceWork__c workRecord) {
        List<Mig_FreeeInvoiceLineWork__c> lines = activeLines(workRecord);
        if (lines.isEmpty()) {
            return false;
        }
        for (Mig_FreeeInvoiceLineWork__c line : lines) {
            if (line.ConfirmedProductMaster__c == null) {
                return false;
            }
        }
        return true;
    }

    private static Set<Id> confirmedProductIds(Mig_FreeeInvoiceWork__c workRecord) {
        Set<Id> result = new Set<Id>();
        for (Mig_FreeeInvoiceLineWork__c line : activeLines(workRecord)) {
            if (line.ConfirmedProductMaster__c != null) {
                result.add(line.ConfirmedProductMaster__c);
            }
        }
        return result;
    }

    private static List<Mig_FreeeInvoiceLineWork__c> activeLines(
        Mig_FreeeInvoiceWork__c workRecord
    ) {
        List<Mig_FreeeInvoiceLineWork__c> result =
            new List<Mig_FreeeInvoiceLineWork__c>();
        if (workRecord.InvoiceLineWorks__r == null) {
            return result;
        }
        for (Mig_FreeeInvoiceLineWork__c line : workRecord.InvoiceLineWorks__r) {
            if (line.ImportStatus__c != Mig_FreeeInvoiceWorkService.STATUS_EXCLUDED) {
                result.add(line);
            }
        }
        return result;
    }

    private static Date earliestTargetStart(
        List<Mig_FreeeInvoiceWork__c> works,
        String updateCycle
    ) {
        Date earliest;
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            Date candidate = effectivePeriodStart(workRecord, updateCycle);
            if (candidate != null && (earliest == null || candidate < earliest)) {
                earliest = candidate;
            }
        }
        return earliest;
    }

    private static Date effectivePeriodStart(
        Mig_FreeeInvoiceWork__c workRecord,
        String updateCycle
    ) {
        if (workRecord.TargetPeriodStartDate__c != null) {
            return workRecord.TargetPeriodStartDate__c;
        }
        if (workRecord.BillingDate__c == null) {
            return null;
        }
        return Date.newInstance(
            workRecord.BillingDate__c.year(),
            workRecord.BillingDate__c.month(),
            1
        );
    }

    private static Date effectivePeriodEnd(
        Mig_FreeeInvoiceWork__c workRecord,
        String updateCycle,
        Boolean oneTime
    ) {
        if (workRecord.TargetPeriodEndDate__c != null) {
            return workRecord.TargetPeriodEndDate__c;
        }
        Date startDate = effectivePeriodStart(workRecord, updateCycle);
        if (startDate == null) {
            return null;
        }
        Integer months = updateCycle == UPDATE_YEARLY && !oneTime ? 12 : 1;
        return startDate.addMonths(months).addDays(-1);
    }

    private static Boolean contractContainsTarget(
        Contract__c contractRecord,
        Mig_FreeeInvoiceWork__c workRecord
    ) {
        Date target = workRecord.TargetPeriodStartDate__c == null
            ? workRecord.BillingDate__c
            : workRecord.TargetPeriodStartDate__c;
        if (target == null) {
            return false;
        }
        return (contractRecord.StartDate__c == null || contractRecord.StartDate__c <= target)
            && (contractRecord.EndDate__c == null || contractRecord.EndDate__c >= target);
    }

    private static String periodKey(Id contractId, Date startDate, Date endDate) {
        return String.valueOf(contractId)
            + ':'
            + String.valueOf(startDate)
            + ':'
            + String.valueOf(endDate);
    }

    private static String buildContractName(
        Account accountRecord,
        ProductMaster__c productRecord,
        Boolean oneTime
    ) {
        String accountName = accountRecord == null ? '取引先未設定' : accountRecord.Name;
        String productName = productRecord == null ? '商品未設定' : productRecord.Name;
        return accountName
            + ' '
            + productName
            + (oneTime ? ' 単発契約' : ' Freee自動請求契約');
    }
}

public with sharing class Mig_FreeeInvoiceFinalizeService {
    public static void finalizeAllReady() {
        List<Id> workIds = new List<Id>();
        for (Mig_FreeeInvoiceWork__c workRecord : [
            SELECT Id
            FROM Mig_FreeeInvoiceWork__c
            WHERE ImportStatus__c = :Mig_FreeeInvoiceWorkService.STATUS_READY
            ORDER BY BillingDate__c ASC, CreatedDate ASC
            LIMIT 5000
        ]) {
            workIds.add(workRecord.Id);
        }
        finalizeByWorkIds(workIds);
    }

    public static void finalizeByWorkIds(List<Id> workIds) {
        if (workIds == null || workIds.isEmpty()) {
            return;
        }

        List<Mig_FreeeInvoiceWork__c> works = [
            SELECT Id,
                   ExternalKey__c,
                   FreeeInvoiceId__c,
                   FreeeInvoiceNumber__c,
                   FreeePartnerId__c,
                   BillingDate__c,
                   PaymentDate__c,
                   Subject__c,
                   InvoiceAmount__c,
                   TaxAmount__c,
                   PaidAmount__c,
                   UnpaidAmount__c,
                   SendStatus__c,
                   PaymentStatus__c,
                   TargetPeriodStartDate__c,
                   TargetPeriodEndDate__c,
                   ResolvedAccount__c,
                   ResolvedContract__c,
                   ResolvedContractPeriod__c,
                   CreatedInvoice__c,
                   ImportStatus__c,
                   ValidationMessage__c
            FROM Mig_FreeeInvoiceWork__c
            WHERE Id IN :workIds
        ];
        if (works.isEmpty()) {
            return;
        }

        Set<Id> requestedWorkIds = new Set<Id>();
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            requestedWorkIds.add(workRecord.Id);
        }

        List<Mig_FreeeInvoiceLineWork__c> lineWorks = [
            SELECT Id,
                   InvoiceWork__c,
                   ExternalKey__c,
                   FreeeLineId__c,
                   Description__c,
                   Quantity__c,
                   Unit__c,
                   UnitPrice__c,
                   LineAmount__c,
                   TaxRate__c,
                   TaxAmount__c,
                   ConfirmedProductMaster__c,
                   ConfirmedProductMaster__r.Name,
                   ResolvedContractLineItem__c,
                   CreatedInvoiceLine__c,
                   ImportStatus__c,
                   ResolveMessage__c
            FROM Mig_FreeeInvoiceLineWork__c
            WHERE InvoiceWork__c IN :requestedWorkIds
              AND ImportStatus__c != :Mig_FreeeInvoiceWorkService.STATUS_EXCLUDED
        ];

        Map<Id, List<Mig_FreeeInvoiceLineWork__c>> linesByWork = new Map<Id, List<Mig_FreeeInvoiceLineWork__c>>();
        for (Mig_FreeeInvoiceLineWork__c lineWork : lineWorks) {
            if (!linesByWork.containsKey(lineWork.InvoiceWork__c)) {
                linesByWork.put(lineWork.InvoiceWork__c, new List<Mig_FreeeInvoiceLineWork__c>());
            }
            linesByWork.get(lineWork.InvoiceWork__c).add(lineWork);
        }

        Map<Decimal, List<Invoice__c>> existingInvoicesByFreeeId = findExistingInvoicesByFreeeId(works);
        List<Invoice__c> invoicesToUpsert = new List<Invoice__c>();
        List<Invoice__c> existingInvoicesToLink = new List<Invoice__c>();
        Map<String, Mig_FreeeInvoiceWork__c> workByExternalKey = new Map<String, Mig_FreeeInvoiceWork__c>();
        Map<Id, Id> invoiceIdByWorkId = new Map<Id, Id>();
        Set<Id> newWorkIds = new Set<Id>();
        Set<Id> existingWorkIds = new Set<Id>();
        Set<Id> existingInvoiceIds = new Set<Id>();
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            List<String> errors = validateWork(workRecord, linesByWork.get(workRecord.Id));
            errors.addAll(validateExistingInvoiceMatch(workRecord, existingInvoicesByFreeeId));
            if (!errors.isEmpty()) {
                workRecord.ImportStatus__c = Mig_FreeeInvoiceWorkService.STATUS_NEEDS_REVIEW;
                workRecord.ValidationMessage__c = String.join(errors, '\n');
                continue;
            }
            Invoice__c invoiceRecord = toInvoice(workRecord);
            Invoice__c existingInvoice = getSingleExistingInvoice(workRecord, existingInvoicesByFreeeId);
            if (existingInvoice != null) {
                existingInvoicesToLink.add(new Invoice__c(
                    Id = existingInvoice.Id,
                    Freee_External_Key__c = workRecord.ExternalKey__c,
                    MigrationSourceWork__c = workRecord.Id,
                    MigrationImportedAt__c = System.now()
                ));
                invoiceIdByWorkId.put(workRecord.Id, existingInvoice.Id);
                existingWorkIds.add(workRecord.Id);
                existingInvoiceIds.add(existingInvoice.Id);
            } else {
                invoicesToUpsert.add(invoiceRecord);
                newWorkIds.add(workRecord.Id);
            }
            workByExternalKey.put(workRecord.ExternalKey__c, workRecord);
        }

        if (!existingInvoicesToLink.isEmpty()) {
            update existingInvoicesToLink;
        }
        if (!invoicesToUpsert.isEmpty()) {
            upsert invoicesToUpsert Invoice__c.Freee_External_Key__c;
        }

        Map<String, Invoice__c> invoiceByExternalKey = new Map<String, Invoice__c>();
        if (!workByExternalKey.isEmpty()) {
            for (Invoice__c invoiceRecord : [
                SELECT Id, Freee_External_Key__c
                FROM Invoice__c
                WHERE Freee_External_Key__c IN :workByExternalKey.keySet()
            ]) {
                invoiceByExternalKey.put(invoiceRecord.Freee_External_Key__c, invoiceRecord);
                Mig_FreeeInvoiceWork__c workRecord = workByExternalKey.get(invoiceRecord.Freee_External_Key__c);
                if (workRecord != null) {
                    invoiceIdByWorkId.put(workRecord.Id, invoiceRecord.Id);
                }
            }
        }

        List<InvoiceLine__c> invoiceLinesToUpsert = new List<InvoiceLine__c>();
        Map<String, Mig_FreeeInvoiceLineWork__c> lineWorkByExternalKey = new Map<String, Mig_FreeeInvoiceLineWork__c>();
        List<Mig_FreeeInvoiceLineWork__c> existingLineWorkUpdates = new List<Mig_FreeeInvoiceLineWork__c>();
        Map<String, List<InvoiceLine__c>> existingLinesByMatchKey = getExistingLinesByMatchKey(existingInvoiceIds);
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            Id invoiceId = invoiceIdByWorkId.get(workRecord.Id);
            if (invoiceId == null) {
                continue;
            }
            Boolean allExistingLinesMatched = true;
            for (Mig_FreeeInvoiceLineWork__c lineWork : linesByWork.get(workRecord.Id)) {
                if (existingWorkIds.contains(workRecord.Id)) {
                    InvoiceLine__c existingLine = findExistingLine(invoiceId, lineWork, existingLinesByMatchKey);
                    if (existingLine == null) {
                        allExistingLinesMatched = false;
                    } else {
                        lineWork.CreatedInvoiceLine__c = existingLine.Id;
                        lineWork.ImportStatus__c = Mig_FreeeInvoiceWorkService.STATUS_IMPORTED;
                        existingLineWorkUpdates.add(lineWork);
                    }
                } else {
                    invoiceLinesToUpsert.add(toInvoiceLine(invoiceId, lineWork));
                    lineWorkByExternalKey.put(lineWork.ExternalKey__c, lineWork);
                }
            }
            if (!allExistingLinesMatched) {
                workRecord.ImportStatus__c = Mig_FreeeInvoiceWorkService.STATUS_NEEDS_REVIEW;
                workRecord.ValidationMessage__c = '同じfreee請求書IDのSalesforce請求は存在しますが、すべての請求明細を照合できませんでした。既存の請求明細と移行Workの明細を確認してください。';
                continue;
            }
            workRecord.CreatedInvoice__c = invoiceId;
            workRecord.ImportStatus__c = Mig_FreeeInvoiceWorkService.STATUS_IMPORTED;
            workRecord.ValidationMessage__c = null;
        }

        if (!invoiceLinesToUpsert.isEmpty()) {
            upsert invoiceLinesToUpsert InvoiceLine__c.Freee_External_Key__c;
        }

        List<Invoice__c> invoicesToMarkSynced = new List<Invoice__c>();
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            if (!newWorkIds.contains(workRecord.Id)) {
                continue;
            }
            Id invoiceId = invoiceIdByWorkId.get(workRecord.Id);
            if (invoiceId != null) {
                invoicesToMarkSynced.add(new Invoice__c(
                    Id = invoiceId,
                    Sent_To_Freee__c = true,
                    Freee_Sync_Status__c = 'Success'
                ));
            }
        }
        if (!invoicesToMarkSynced.isEmpty()) {
            update invoicesToMarkSynced;
        }

        if (!lineWorkByExternalKey.isEmpty()) {
            for (InvoiceLine__c createdLine : [
                SELECT Id, Freee_External_Key__c
                FROM InvoiceLine__c
                WHERE Freee_External_Key__c IN :lineWorkByExternalKey.keySet()
            ]) {
                Mig_FreeeInvoiceLineWork__c sourceLineWork = lineWorkByExternalKey.get(createdLine.Freee_External_Key__c);
                sourceLineWork.CreatedInvoiceLine__c = createdLine.Id;
                sourceLineWork.ImportStatus__c = Mig_FreeeInvoiceWorkService.STATUS_IMPORTED;
            }
        }

        update works;
        if (!lineWorkByExternalKey.isEmpty()) {
            update lineWorkByExternalKey.values();
        }
        if (!existingLineWorkUpdates.isEmpty()) {
            update existingLineWorkUpdates;
        }
        updateContractLineItems(lineWorks, invoiceIdByWorkId, works);
    }

    private static Invoice__c toInvoice(Mig_FreeeInvoiceWork__c workRecord) {
        return new Invoice__c(
            Account__c = workRecord.ResolvedAccount__c,
            ParentContract__c = workRecord.ResolvedContract__c,
            ContractPeriod__c = workRecord.ResolvedContractPeriod__c,
            Billing_Date__c = workRecord.BillingDate__c,
            Payment_Date__c = workRecord.PaymentDate__c,
            Subject__c = String.isBlank(workRecord.Subject__c) ? workRecord.FreeeInvoiceNumber__c : workRecord.Subject__c,
            InvoiceAmount__c = workRecord.InvoiceAmount__c,
            TaxAmount__c = workRecord.TaxAmount__c,
            AmountWithTax__c = workRecord.InvoiceAmount__c,
            PaidAmount__c = workRecord.PaidAmount__c,
            UnpaidAmount__c = workRecord.UnpaidAmount__c,
            Freee_Invoice_Id__c = Mig_FreeeInvoiceWorkService.toDecimal(workRecord.FreeeInvoiceId__c),
            Freee_Invoice_Number__c = workRecord.FreeeInvoiceNumber__c,
            Freee_Partner_Id__c = Mig_FreeeInvoiceWorkService.toDecimal(workRecord.FreeePartnerId__c),
            Freee_Invoice_Status__c = workRecord.SendStatus__c,
            PaymentStatus__c = workRecord.PaymentStatus__c,
            Freee_Sync_Status__c = 'Success',
            Sent_To_Freee__c = false,
            Freee_Account_Item_Picklist__c = 'Sales',
            Freee_External_Key__c = workRecord.ExternalKey__c,
            MigrationSourceWork__c = workRecord.Id,
            MigrationImportedAt__c = System.now(),
            TargetPeriodStartDate__c = workRecord.TargetPeriodStartDate__c,
            TargetPeriodEndDate__c = workRecord.TargetPeriodEndDate__c
        );
    }

    private static InvoiceLine__c toInvoiceLine(Id invoiceId, Mig_FreeeInvoiceLineWork__c lineWork) {
        Decimal quantity = lineWork.Quantity__c == null || lineWork.Quantity__c == 0 ? 1 : lineWork.Quantity__c;
        Decimal unitPrice = lineWork.UnitPrice__c;
        if (unitPrice == null && lineWork.LineAmount__c != null && quantity != 0) {
            unitPrice = lineWork.LineAmount__c / quantity;
        }
        return new InvoiceLine__c(
            Invoice__c = invoiceId,
            ProductMaster__c = lineWork.ConfirmedProductMaster__c,
            Description__c = lineWork.Description__c,
            Quantity__c = quantity,
            Unit__c = lineWork.Unit__c,
            Unit_Price__c = unitPrice,
            Tax_Rate__c = lineWork.TaxRate__c == null ? 10 : lineWork.TaxRate__c,
            TaxAmount__c = lineWork.TaxAmount__c,
            AmountWithTax__c = lineWork.TaxAmount__c == null ? lineWork.LineAmount__c : lineWork.LineAmount__c + lineWork.TaxAmount__c,
            Freee_Line_Id__c = lineWork.FreeeLineId__c,
            Freee_External_Key__c = lineWork.ExternalKey__c,
            MigrationSourceLineWork__c = lineWork.Id
        );
    }

    private static Map<String, List<InvoiceLine__c>> getExistingLinesByMatchKey(Set<Id> invoiceIds) {
        Map<String, List<InvoiceLine__c>> linesByMatchKey = new Map<String, List<InvoiceLine__c>>();
        if (invoiceIds == null || invoiceIds.isEmpty()) {
            return linesByMatchKey;
        }
        for (InvoiceLine__c lineRecord : [
            SELECT Id,
                   Invoice__c,
                   ProductMaster__c,
                   Quantity__c,
                   AmountWithTax__c
            FROM InvoiceLine__c
            WHERE Invoice__c IN :invoiceIds
        ]) {
            String key = matchKey(
                lineRecord.Invoice__c,
                lineRecord.ProductMaster__c,
                lineRecord.Quantity__c,
                lineRecord.AmountWithTax__c
            );
            if (!linesByMatchKey.containsKey(key)) {
                linesByMatchKey.put(key, new List<InvoiceLine__c>());
            }
            linesByMatchKey.get(key).add(lineRecord);
        }
        return linesByMatchKey;
    }

    private static InvoiceLine__c findExistingLine(
        Id invoiceId,
        Mig_FreeeInvoiceLineWork__c lineWork,
        Map<String, List<InvoiceLine__c>> existingLinesByMatchKey
    ) {
        Decimal amountWithTax = lineWork.TaxAmount__c == null
            ? lineWork.LineAmount__c
            : lineWork.LineAmount__c + lineWork.TaxAmount__c;
        String key = matchKey(invoiceId, lineWork.ConfirmedProductMaster__c, lineWork.Quantity__c, amountWithTax);
        List<InvoiceLine__c> candidates = existingLinesByMatchKey.get(key);
        return candidates == null || candidates.size() != 1 ? null : candidates[0];
    }

    private static String matchKey(Id invoiceId, Id productId, Decimal quantity, Decimal amountWithTax) {
        return String.valueOf(invoiceId)
            + ':'
            + String.valueOf(productId)
            + ':'
            + normalizeDecimal(quantity)
            + ':'
            + normalizeDecimal(amountWithTax);
    }

    private static String normalizeDecimal(Decimal value) {
        return value == null ? '' : String.valueOf(value.setScale(2));
    }

    private static List<String> validateWork(Mig_FreeeInvoiceWork__c workRecord, List<Mig_FreeeInvoiceLineWork__c> lineWorks) {
        List<String> errors = new List<String>();
        if (workRecord.ImportStatus__c != Mig_FreeeInvoiceWorkService.STATUS_READY) {
            errors.add('請求書移行Workの取込ステータスが反映可能ではありません。検証を実行し、要確認事項を解消してください。');
        }
        if (Mig_FreeeInvoiceWorkService.toDecimal(workRecord.FreeeInvoiceId__c) == null) {
            errors.add('freee請求書IDが不正です。freee請求書IDに数値が入っているか確認してください。');
        }
        if (workRecord.ResolvedAccount__c == null) {
            errors.add('取引先を特定できません。freee取引先IDまたは取引先名の対応を確認してください。');
        }
        if (workRecord.ResolvedContract__c == null) {
            errors.add('契約管理を特定できません。取引先に有効な契約管理があるか確認してください。');
        }
        if (workRecord.ResolvedContractPeriod__c == null) {
            errors.add('契約期間を特定できません。請求日を含む契約期間があるか確認してください。');
        }
        if (String.isBlank(workRecord.ExternalKey__c)) {
            errors.add('移行用の一意キーが作成できていません。freee請求書IDまたは事業所IDを確認してください。');
        }
        if (lineWorks == null || lineWorks.isEmpty()) {
            errors.add('請求明細Workがありません。freee請求書に明細が存在するか確認してください。');
        } else {
            for (Mig_FreeeInvoiceLineWork__c lineWork : lineWorks) {
                if (lineWork.ConfirmedProductMaster__c == null) {
                    errors.add('商品マスタが未確定の請求明細Workがあります。候補商品を確認し、商品マスタを確定してください。');
                    break;
                }
            }
        }
        if (errors.isEmpty() && lineWorks != null) {
            for (Mig_FreeeInvoiceLineWork__c lineWork : lineWorks) {
                if (isLowSimilarityPriceMatch(lineWork)) {
                    errors.add(
                        '請求明細の件名と商品マスタ名が類似していないため、請求作成を停止しました。'
                        + '金額一致だけで商品が選ばれている可能性があります。'
                        + '明細「' + safeText(lineWork.Description__c) + '」の商品マスタを確認してください。'
                    );
                    break;
                }
            }
        }
        return errors;
    }

    private static Boolean isLowSimilarityPriceMatch(Mig_FreeeInvoiceLineWork__c lineWork) {
        if (lineWork == null || String.isBlank(lineWork.ResolveMessage__c)) {
            return false;
        }
        Boolean priceOnlyMatch = lineWork.ResolveMessage__c == 'Matched by unit price.'
            || lineWork.ResolveMessage__c == 'Matched by single-line amount.';
        if (!priceOnlyMatch || lineWork.ConfirmedProductMaster__r == null) {
            return false;
        }
        return textSimilarity(lineWork.Description__c, lineWork.ConfirmedProductMaster__r.Name) < 0.35;
    }

    private static Decimal textSimilarity(String leftText, String rightText) {
        String left = normalizeForSimilarity(leftText);
        String right = normalizeForSimilarity(rightText);
        if (String.isBlank(left) || String.isBlank(right)) {
            return 0;
        }
        if (left.contains(right) || right.contains(left)) {
            return 1;
        }

        Set<String> leftChars = toCharacterSet(left);
        Set<String> rightChars = toCharacterSet(right);
        Set<String> unionChars = new Set<String>();
        unionChars.addAll(leftChars);
        unionChars.addAll(rightChars);
        if (unionChars.isEmpty()) {
            return 0;
        }

        Integer intersectionCount = 0;
        for (String characterValue : leftChars) {
            if (rightChars.contains(characterValue)) {
                intersectionCount++;
            }
        }
        return Decimal.valueOf(intersectionCount) / Decimal.valueOf(unionChars.size());
    }

    private static Set<String> toCharacterSet(String source) {
        Set<String> values = new Set<String>();
        if (String.isBlank(source)) {
            return values;
        }
        for (Integer i = 0; i < source.length(); i++) {
            values.add(source.substring(i, i + 1));
        }
        return values;
    }

    private static String normalizeForSimilarity(String source) {
        if (String.isBlank(source)) {
            return '';
        }
        String normalized = source.toLowerCase();
        List<String> removableValues = new List<String>{
            ' ', '　', '_', '-', '・', '（', '）', '(', ')', '[', ']', '【', '】',
            '「', '」', '『', '』', ',', '，', '.', '．', '/', '／', ':', '：',
            ';', '；', '+', '＋', '株式会社', '有限会社', '合同会社', '年間利用料',
            '月額', '初期費用'
        };
        for (String value : removableValues) {
            normalized = normalized.replace(value, '');
        }
        return normalized;
    }

    private static String safeText(String source) {
        return String.isBlank(source) ? '(空白)' : source;
    }

    private static Map<Decimal, List<Invoice__c>> findExistingInvoicesByFreeeId(List<Mig_FreeeInvoiceWork__c> works) {
        Set<Decimal> freeeInvoiceIds = new Set<Decimal>();
        for (Mig_FreeeInvoiceWork__c workRecord : works) {
            Decimal freeeInvoiceId = Mig_FreeeInvoiceWorkService.toDecimal(workRecord.FreeeInvoiceId__c);
            if (freeeInvoiceId != null) {
                freeeInvoiceIds.add(freeeInvoiceId);
            }
        }

        Map<Decimal, List<Invoice__c>> invoicesByFreeeId = new Map<Decimal, List<Invoice__c>>();
        if (freeeInvoiceIds.isEmpty()) {
            return invoicesByFreeeId;
        }

        for (Invoice__c invoiceRecord : [
            SELECT Id,
                   Freee_Invoice_Id__c,
                   Freee_External_Key__c,
                   MigrationSourceWork__c
            FROM Invoice__c
            WHERE Freee_Invoice_Id__c IN :freeeInvoiceIds
        ]) {
            if (!invoicesByFreeeId.containsKey(invoiceRecord.Freee_Invoice_Id__c)) {
                invoicesByFreeeId.put(invoiceRecord.Freee_Invoice_Id__c, new List<Invoice__c>());
            }
            invoicesByFreeeId.get(invoiceRecord.Freee_Invoice_Id__c).add(invoiceRecord);
        }
        return invoicesByFreeeId;
    }

    private static List<String> validateExistingInvoiceMatch(
        Mig_FreeeInvoiceWork__c workRecord,
        Map<Decimal, List<Invoice__c>> existingInvoicesByFreeeId
    ) {
        List<String> errors = new List<String>();
        Decimal freeeInvoiceId = Mig_FreeeInvoiceWorkService.toDecimal(workRecord.FreeeInvoiceId__c);
        if (freeeInvoiceId == null) {
            return errors;
        }

        List<Invoice__c> existingInvoices = existingInvoicesByFreeeId.get(freeeInvoiceId);
        if (existingInvoices == null || existingInvoices.isEmpty()) {
            return errors;
        }
        if (existingInvoices.size() > 1) {
            errors.add('同じfreee請求書IDを持つSalesforce請求が複数存在します。freee請求書ID=' + String.valueOf(freeeInvoiceId));
            return errors;
        }

        Invoice__c existingInvoice = existingInvoices[0];
        if (!String.isBlank(existingInvoice.Freee_External_Key__c)
            && existingInvoice.Freee_External_Key__c != workRecord.ExternalKey__c
        ) {
            errors.add('既存のSalesforce請求のfreee外部キーが、この請求書移行Workと一致しません。既存請求と移行Workの対応を確認してください。');
        }
        if (existingInvoice.MigrationSourceWork__c != null && existingInvoice.MigrationSourceWork__c != workRecord.Id) {
            errors.add('既存のSalesforce請求は別の請求書移行Workに紐づいています。重複取込または紐づけ誤りがないか確認してください。');
        }
        return errors;
    }

    private static Invoice__c getSingleExistingInvoice(
        Mig_FreeeInvoiceWork__c workRecord,
        Map<Decimal, List<Invoice__c>> existingInvoicesByFreeeId
    ) {
        Decimal freeeInvoiceId = Mig_FreeeInvoiceWorkService.toDecimal(workRecord.FreeeInvoiceId__c);
        if (freeeInvoiceId == null) {
            return null;
        }
        List<Invoice__c> existingInvoices = existingInvoicesByFreeeId.get(freeeInvoiceId);
        return existingInvoices == null || existingInvoices.size() != 1 ? null : existingInvoices[0];
    }

    private static void updateContractLineItems(
        List<Mig_FreeeInvoiceLineWork__c> lineWorks,
        Map<Id, Id> invoiceIdByWorkId,
        List<Mig_FreeeInvoiceWork__c> works
    ) {
        Map<Id, Mig_FreeeInvoiceWork__c> workById = new Map<Id, Mig_FreeeInvoiceWork__c>(works);
        Map<Id, Id> invoiceIdByCliId = new Map<Id, Id>();
        for (Mig_FreeeInvoiceLineWork__c lineWork : lineWorks) {
            if (lineWork.ResolvedContractLineItem__c == null) {
                continue;
            }
            Mig_FreeeInvoiceWork__c workRecord = workById.get(lineWork.InvoiceWork__c);
            Id invoiceId = workRecord == null ? null : invoiceIdByWorkId.get(workRecord.Id);
            if (invoiceId != null) {
                invoiceIdByCliId.put(lineWork.ResolvedContractLineItem__c, invoiceId);
            }
        }
        List<ContractLineItem__c> updates = new List<ContractLineItem__c>();
        if (!invoiceIdByCliId.isEmpty()) {
            for (ContractLineItem__c lineRecord : [
                SELECT Id, RelatedInvoice__c
                FROM ContractLineItem__c
                WHERE Id IN :invoiceIdByCliId.keySet()
            ]) {
                Id invoiceId = invoiceIdByCliId.get(lineRecord.Id);
                if (lineRecord.RelatedInvoice__c == null) {
                    updates.add(new ContractLineItem__c(
                        Id = lineRecord.Id,
                        RelatedInvoice__c = invoiceId
                    ));
                }
            }
        }
        if (!updates.isEmpty()) {
            update updates;
        }
    }
}

public with sharing class OppContractInvoiceService {
    public class CreationResult {
        public Id contractId;
        public Id invoiceId;
        public Integer invoiceLineCount;
    }

    private static final String CLOSED_WON = 'Closed Won';
    private static final String ACCEPTED = 'Accepted';
    private static final String CONTRACT_STATUS_DRAFT = 'Draft';
    private static final String INVOICE_ACCOUNT_ITEM_SALES = 'Sales';
    private static final String QUOTATION_ACCOUNT_ITEM_SALES = 'sales';
    private static final String UPDATE_MONTHLY = '月';
    private static final String UPDATE_YEARLY = '年';
    private static final String INVOICE_STATUS_BILLED = '請求済';
    private static final String PERIOD_STATUS_CREATED = '作成済';
    private static final String FREEE_STATUS_NOT_SYNCED = '未連携';
    private static final String SEND_WAITING = '送付待ち';
    private static final String PAYMENT_WAITING = '決済待ち';
    private static final Decimal TAX_RATE = 10;

    public static CreationResult createFromOpportunity(Id opportunityId) {
        if (opportunityId == null) {
            throw new AuraHandledException('取引IDが指定されていません。');
        }

        Opportunity__c opportunityRecord = getOpportunity(opportunityId);
        validateOpportunity(opportunityRecord);

        if (hasExistingContract(opportunityId)) {
            throw new AuraHandledException('この取引には既に契約が作成されています。');
        }
        if (hasExistingInvoice(opportunityId)) {
            throw new AuraHandledException('この取引には既に請求が作成されています。');
        }

        Quotation__c acceptedQuotation = getAcceptedQuotation(opportunityId);
        validateAcceptedQuotation(acceptedQuotation);

        List<QuotationLine__c> quotationLines = getQuotationLines(acceptedQuotation.Id);
        validateQuotationLines(quotationLines);

        Contract__c contractRecord = createContract(opportunityRecord, acceptedQuotation);
        ContractPeriod__c periodRecord = createInitialContractPeriod(contractRecord);
        Invoice__c invoiceRecord = createInvoice(
            opportunityId,
            contractRecord.Id,
            periodRecord.Id,
            acceptedQuotation,
            periodRecord.PeriodStartDate__c,
            periodRecord.PeriodEndDate__c
        );
        Integer lineCount = createInvoiceLines(
            invoiceRecord.Id,
            contractRecord.ContractUpdate__c,
            quotationLines
        );
        createInitialContractLines(contractRecord, periodRecord.Id, invoiceRecord.Id, quotationLines);
        update new ContractPeriod__c(
            Id = periodRecord.Id,
            RelatedInvoice__c = invoiceRecord.Id,
            InvoiceCreationStatus__c = PERIOD_STATUS_CREATED,
            FreeeSyncStatus__c = FREEE_STATUS_NOT_SYNCED
        );

        CreationResult result = new CreationResult();
        result.contractId = contractRecord.Id;
        result.invoiceId = invoiceRecord.Id;
        result.invoiceLineCount = lineCount;
        return result;
    }

    private static Opportunity__c getOpportunity(Id opportunityId) {
        List<Opportunity__c> opportunities = [
            SELECT Id,
                   Name,
                   Account__c,
                   ACV__c,
                   ARR__c,
                   ContractUpdate__c,
                   Description__c,
                   ExpectedDuration__c,
                   MRR__c,
                   ProductCategory__c,
                   PlanCategory__c,
                   AccountCount__c,
                   Pricebook2__c,
                   StageName__c,
                   StartDate__c,
                   Event__c
            FROM Opportunity__c
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (opportunities.isEmpty()) {
            throw new AuraHandledException('対象の取引が見つかりません。');
        }

        return opportunities[0];
    }

    private static void validateOpportunity(Opportunity__c opportunityRecord) {
        List<String> errors = new List<String>();

        if (opportunityRecord.StageName__c != CLOSED_WON) {
            errors.add('取引が受注状態ではありません。');
        }
        if (opportunityRecord.Account__c == null) {
            errors.add('取引先が設定されていません。');
        }
        if (opportunityRecord.StartDate__c == null) {
            errors.add('契約日として使用する開始日が設定されていません。');
        }

        throwIfErrors(errors);
    }

    private static Boolean hasExistingContract(Id opportunityId) {
        return [
            SELECT COUNT()
            FROM Contract__c
            WHERE Oppotunity__c = :opportunityId
        ] > 0;
    }

    private static Boolean hasExistingInvoice(Id opportunityId) {
        return [
            SELECT COUNT()
            FROM Invoice__c
            WHERE ParentOpportunity__c = :opportunityId
        ] > 0;
    }

    private static Quotation__c getAcceptedQuotation(Id opportunityId) {
        List<Quotation__c> quotations = [
            SELECT Id,
                   Account__c,
                   Freee_Account_Item_Picklist__c,
                   Freee_Partner_Id__c,
                   Memo__c,
                   Oppotunity__c,
                   Quotation_Status__c,
                   Subject__c
            FROM Quotation__c
            WHERE Oppotunity__c = :opportunityId
              AND Quotation_Status__c = :ACCEPTED
            ORDER BY Issue_Date__c DESC, CreatedDate DESC
            LIMIT 2
        ];

        if (quotations.size() > 1) {
            throw new AuraHandledException('Accepted の見積が複数存在します。1件にしてから契約・請求を作成してください。');
        }
        return quotations.isEmpty() ? null : quotations[0];
    }

    private static void validateAcceptedQuotation(Quotation__c quotationRecord) {
        List<String> errors = new List<String>();

        if (quotationRecord == null) {
            errors.add('Accepted の見積が見つかりません。');
        } else {
            if (quotationRecord.Account__c == null) {
                errors.add('見積に取引先が設定されていません。');
            }
            if (String.isBlank(quotationRecord.Subject__c)) {
                errors.add('見積の件名が設定されていません。');
            }
            if (String.isBlank(quotationRecord.Freee_Account_Item_Picklist__c)) {
                errors.add('見積の Freee計上科目が設定されていません。');
            }
        }

        throwIfErrors(errors);
    }

    private static List<QuotationLine__c> getQuotationLines(Id quotationId) {
        return [
            SELECT Id,
                   Description__c,
                   Freee_Account_Item_Id__c,
                   Line_Amount__c,
                   ProductMaster__c,
                   Quantity__c,
                   Tax_Rate__c,
                   Unit__c,
                   Unit_Price__c,
                   Withholding__c,
                   ProductMaster__r.Name,
                   ProductMaster__r.ProductType__c,
                   ProductMaster__r.BillingTiming__c,
                   ProductMaster__r.AnnualMonthlyPrice__c,
                   ProductMaster__r.MRR_Target__c,
                   ProductMaster__r.ARR_Target__c
            FROM QuotationLine__c
            WHERE Quotation__c = :quotationId
            ORDER BY CreatedDate ASC
        ];
    }

    private static void validateQuotationLines(List<QuotationLine__c> quotationLines) {
        List<String> errors = new List<String>();

        if (quotationLines == null || quotationLines.isEmpty()) {
            errors.add('見積明細がありません。');
        } else {
            for (QuotationLine__c line : quotationLines) {
                if (String.isBlank(line.Description__c)) {
                    errors.add('見積明細の品名が設定されていません。');
                    break;
                }
                if (line.Quantity__c == null || line.Quantity__c <= 0) {
                    errors.add('見積明細の数量は 0 より大きくしてください。');
                    break;
                }
                if (line.Unit_Price__c == null || line.Unit_Price__c <= 0) {
                    errors.add('見積明細の単価は 0 より大きくしてください。');
                    break;
                }
                if (String.isBlank(line.Tax_Rate__c)) {
                    errors.add('見積明細の税率が設定されていません。');
                    break;
                }
            }
        }

        throwIfErrors(errors);
    }

    private static Contract__c createContract(
        Opportunity__c opportunityRecord,
        Quotation__c acceptedQuotation
    ) {
        Contract__c contractRecord = new Contract__c(
            Account__c = opportunityRecord.Account__c,
            ACV__c = opportunityRecord.ACV__c,
            ARR__c = opportunityRecord.ARR__c,
            ContractName__c = buildContractName(opportunityRecord),
            ContractUpdate__c = opportunityRecord.ContractUpdate__c,
            Description__c = opportunityRecord.Description__c,
            EndDate__c = calculateContractEndDate(opportunityRecord),
            Event__c = opportunityRecord.Event__c,
            ExpectedDuration__c = opportunityRecord.ExpectedDuration__c,
            MRR__c = opportunityRecord.MRR__c,
            Oppotunity__c = opportunityRecord.Id,
            ProductCategory__c = opportunityRecord.ProductCategory__c,
            PlanCategory__c = opportunityRecord.PlanCategory__c,
            AccountCount__c = opportunityRecord.AccountCount__c,
            Pricebook2__c = opportunityRecord.Pricebook2__c,
            SourceQuotation__c = acceptedQuotation.Id,
            StartDate__c = opportunityRecord.StartDate__c,
            Status__c = CONTRACT_STATUS_DRAFT
        );
        insert contractRecord;
        return contractRecord;
    }

    private static ContractPeriod__c createInitialContractPeriod(Contract__c contractRecord) {
        ContractPeriod__c periodRecord = new ContractPeriod__c(
            Contract__c = contractRecord.Id,
            ContractUpdate__c = contractRecord.ContractUpdate__c,
            PeriodStartDate__c = contractRecord.StartDate__c,
            PeriodEndDate__c = calculatePeriodEndDate(
                contractRecord.StartDate__c,
                contractRecord.ContractUpdate__c
            ),
            RenewalCount__c = 0,
            IsInitialPeriod__c = true,
            InvoiceCreationStatus__c = '未作成',
            FreeeSyncStatus__c = FREEE_STATUS_NOT_SYNCED
        );
        insert periodRecord;
        return periodRecord;
    }

    private static Invoice__c createInvoice(
        Id opportunityId,
        Id contractId,
        Id contractPeriodId,
        Quotation__c acceptedQuotation
        ,
        Date targetPeriodStartDate,
        Date targetPeriodEndDate
    ) {
        Date billingDate = calculateInitialBillingDate(Date.today());
        Invoice__c invoiceRecord = new Invoice__c(
            Account__c = acceptedQuotation.Account__c,
            Billing_Date__c = billingDate,
            ContractPeriod__c = contractPeriodId,
            Freee_Account_Item_Picklist__c = normalizeInvoiceAccountItemPicklist(
                acceptedQuotation.Freee_Account_Item_Picklist__c
            ),
            Freee_Invoice_Status__c = SEND_WAITING,
            Freee_Partner_Id__c = acceptedQuotation.Freee_Partner_Id__c,
            Freee_Sync_Status__c = 'Processing',
            Memo__c = acceptedQuotation.Memo__c,
            ParentContract__c = contractId,
            ParentOpportunity__c = opportunityId,
            PaymentStatus__c = PAYMENT_WAITING,
            Payment_Date__c = calculatePaymentDueDate(billingDate),
            Subject__c = acceptedQuotation.Subject__c
            ,
            TargetPeriodStartDate__c = targetPeriodStartDate,
            TargetPeriodEndDate__c = targetPeriodEndDate
        );
        insert invoiceRecord;
        return invoiceRecord;
    }

    private static Integer createInvoiceLines(
        Id invoiceId,
        String contractUpdate,
        List<QuotationLine__c> quotationLines
    ) {
        List<InvoiceLine__c> invoiceLinesToInsert = new List<InvoiceLine__c>();

        if (contractUpdate == UPDATE_YEARLY) {
            Decimal annualAmount = 0;
            List<String> annualNames = new List<String>();
            for (QuotationLine__c quotationLine : quotationLines) {
                if (isInitialFee(quotationLine)) {
                    invoiceLinesToInsert.add(buildInvoiceLine(invoiceId, quotationLine, '初期費用'));
                } else {
                    annualAmount += getLineAmount(quotationLine);
                    annualNames.add(getProductOrLineName(quotationLine));
                }
            }
            if (annualAmount > 0) {
                invoiceLinesToInsert.add(new InvoiceLine__c(
                    AmountWithTax__c = annualAmount + calculateTax(annualAmount),
                    Description__c = buildAnnualInvoiceLineName(annualNames),
                    DiscountedUnitPrice__c = annualAmount,
                    Invoice__c = invoiceId,
                    LineType__c = '年間利用料',
                    Quantity__c = 1,
                    TaxAmount__c = calculateTax(annualAmount),
                    Tax_Rate__c = TAX_RATE,
                    Unit__c = '式',
                    Unit_Price__c = annualAmount
                ));
            }
        } else {
            for (QuotationLine__c quotationLine : quotationLines) {
                invoiceLinesToInsert.add(buildInvoiceLine(
                    invoiceId,
                    quotationLine,
                    isInitialFee(quotationLine) ? '初期費用' : '継続費用'
                ));
            }
        }

        if (!invoiceLinesToInsert.isEmpty()) {
            insert invoiceLinesToInsert;
        }

        return invoiceLinesToInsert.size();
    }

    private static InvoiceLine__c buildInvoiceLine(
        Id invoiceId,
        QuotationLine__c quotationLine,
        String lineType
    ) {
        Decimal amount = getLineAmount(quotationLine);
        Decimal taxAmount = calculateTax(amount);
        return new InvoiceLine__c(
            AmountWithTax__c = amount + taxAmount,
            Description__c = quotationLine.Description__c,
            DiscountedUnitPrice__c = quotationLine.Unit_Price__c,
            Freee_Account_Item_Id__c = quotationLine.Freee_Account_Item_Id__c,
            Invoice__c = invoiceId,
            LineType__c = lineType,
            ProductMaster__c = quotationLine.ProductMaster__c,
            Quantity__c = quotationLine.Quantity__c,
            QuotationLine__c = quotationLine.Id,
            TaxAmount__c = taxAmount,
            Tax_Rate__c = Decimal.valueOf(quotationLine.Tax_Rate__c),
            Unit__c = quotationLine.Unit__c,
            Unit_Price__c = quotationLine.Unit_Price__c,
            Withholding__c = quotationLine.Withholding__c
        );
    }

    private static void createInitialContractLines(
        Contract__c contractRecord,
        Id contractPeriodId,
        Id invoiceId,
        List<QuotationLine__c> quotationLines
    ) {
        List<ContractLineItem__c> linesToInsert = new List<ContractLineItem__c>();
        Integer monthCount = contractRecord.ContractUpdate__c == UPDATE_YEARLY ? 12 : 1;
        Date periodMonth = firstDayOfMonth(contractRecord.StartDate__c);

        for (Integer monthIndex = 0; monthIndex < monthCount; monthIndex++) {
            Date monthStart = periodMonth.addMonths(monthIndex);
            for (QuotationLine__c quotationLine : quotationLines) {
                if (isInitialFee(quotationLine) && monthIndex > 0) {
                    continue;
                }

                Decimal revenueAmount = calculateMonthlyRevenueAmount(
                    quotationLine,
                    contractRecord.ContractUpdate__c
                );
                String yearMonth = formatYearMonth(monthStart);
                linesToInsert.add(new ContractLineItem__c(
                    Account__c = contractRecord.Account__c,
                    ARR_Target__c = quotationLine.ProductMaster__r == null
                        ? false
                        : quotationLine.ProductMaster__r.ARR_Target__c,
                    ContractPeriod__c = contractPeriodId,
                    ContractYearMonth__c = yearMonth,
                    InitialFee__c = isInitialFee(quotationLine),
                    InvoiceStatus__c = INVOICE_STATUS_BILLED,
                    MasterContract__c = contractRecord.Id,
                    Month__c = yearMonth,
                    MRR_Target__c = quotationLine.ProductMaster__r == null
                        ? false
                        : quotationLine.ProductMaster__r.MRR_Target__c,
                    PeopleNumber__c = quotationLine.Quantity__c,
                    PeriodStartDate__c = monthStart,
                    PeriodEndDate__c = monthStart.addMonths(1).addDays(-1),
                    Plan__c = contractRecord.Plan__c,
                    ProductMaster__c = quotationLine.ProductMaster__c,
                    QuotationLine__c = quotationLine.Id,
                    RelatedInvoice__c = invoiceId,
                    RevenueAmount__c = revenueAmount,
                    Total__c = revenueAmount
                ));
            }
        }

        if (!linesToInsert.isEmpty()) {
            insert linesToInsert;
        }
    }

    private static String buildContractName(Opportunity__c opportunityRecord) {
        if (opportunityRecord.StartDate__c == null) {
            return opportunityRecord.Name;
        }

        Date contractDate = opportunityRecord.StartDate__c;
        String month = String.valueOf(contractDate.month()).leftPad(2, '0');
        String day = String.valueOf(contractDate.day()).leftPad(2, '0');
        return opportunityRecord.Name
            + '_'
            + String.valueOf(contractDate.year())
            + '-'
            + month
            + '-'
            + day;
    }

    private static Date calculateContractEndDate(Opportunity__c opportunityRecord) {
        if (opportunityRecord.StartDate__c == null) {
            return null;
        }
        if (opportunityRecord.ContractUpdate__c == UPDATE_YEARLY) {
            return opportunityRecord.StartDate__c.addYears(1).addDays(-1);
        }
        return opportunityRecord.StartDate__c.addMonths(1).addDays(-1);
    }

    private static Date calculatePeriodEndDate(Date startDate, String contractUpdate) {
        if (startDate == null) {
            return null;
        }
        if (contractUpdate == UPDATE_YEARLY) {
            return startDate.addYears(1).addDays(-1);
        }
        return startDate.addMonths(1).addDays(-1);
    }

    private static Date calculateInitialBillingDate(Date baseDate) {
        Date candidate = Date.newInstance(baseDate.year(), baseDate.month(), 20);
        if (candidate < baseDate) {
            candidate = candidate.addMonths(1);
        }
        return previousBusinessDay(candidate);
    }

    private static Date calculatePaymentDueDate(Date billingDate) {
        if (billingDate == null) {
            return null;
        }
        Date nextMonth = billingDate.addMonths(1);
        return Date.newInstance(nextMonth.year(), nextMonth.month(), 1)
            .addMonths(1)
            .addDays(-1);
    }

    private static Date previousBusinessDay(Date sourceDate) {
        Date adjustedDate = sourceDate;
        while (isWeekend(adjustedDate)) {
            adjustedDate = adjustedDate.addDays(-1);
        }
        return adjustedDate;
    }

    private static Boolean isWeekend(Date sourceDate) {
        Date weekStart = sourceDate.toStartOfWeek();
        Integer dayOffset = weekStart.daysBetween(sourceDate);
        return dayOffset == 0 || dayOffset == 6;
    }

    private static Decimal calculateMonthlyRevenueAmount(
        QuotationLine__c quotationLine,
        String contractUpdate
    ) {
        if (contractUpdate == UPDATE_YEARLY && !isInitialFee(quotationLine)) {
            if (quotationLine.ProductMaster__r != null
                && quotationLine.ProductMaster__r.AnnualMonthlyPrice__c != null
            ) {
                return quotationLine.ProductMaster__r.AnnualMonthlyPrice__c
                    * nullToOne(quotationLine.Quantity__c);
            }
            return getLineAmount(quotationLine) / 12;
        }
        return getLineAmount(quotationLine);
    }

    private static Boolean isInitialFee(QuotationLine__c quotationLine) {
        if (quotationLine.ProductMaster__r == null) {
            return false;
        }
        return quotationLine.ProductMaster__r.ProductType__c == '初期費用'
            || quotationLine.ProductMaster__r.BillingTiming__c == '初回のみ'
            || quotationLine.ProductMaster__r.ProductType__c == '蛻晄悄雋ｻ逕ｨ'
            || quotationLine.ProductMaster__r.BillingTiming__c == '蛻晏屓縺ｮ縺ｿ';
    }

    private static Decimal getLineAmount(QuotationLine__c quotationLine) {
        if (quotationLine.Line_Amount__c != null) {
            return quotationLine.Line_Amount__c;
        }
        return nullToZero(quotationLine.Unit_Price__c)
            * nullToOne(quotationLine.Quantity__c);
    }

    private static Decimal calculateTax(Decimal amount) {
        if (amount == null) {
            return 0;
        }
        return (amount * TAX_RATE / 100).round(System.RoundingMode.CEILING);
    }

    private static String buildAnnualInvoiceLineName(List<String> sourceNames) {
        List<String> names = new List<String>();
        Set<String> seen = new Set<String>();
        for (String sourceName : sourceNames) {
            if (String.isBlank(sourceName) || seen.contains(sourceName)) {
                continue;
            }
            names.add(sourceName);
            seen.add(sourceName);
        }
        return (names.isEmpty() ? '年間利用料' : String.join(names, '・') + ' 年間利用料');
    }

    private static String getProductOrLineName(QuotationLine__c quotationLine) {
        if (quotationLine.ProductMaster__r != null
            && !String.isBlank(quotationLine.ProductMaster__r.Name)
        ) {
            return quotationLine.ProductMaster__r.Name;
        }
        return quotationLine.Description__c;
    }

    private static Date firstDayOfMonth(Date sourceDate) {
        return Date.newInstance(sourceDate.year(), sourceDate.month(), 1);
    }

    private static String formatYearMonth(Date sourceDate) {
        return String.valueOf(sourceDate.year()) + '/' + String.valueOf(sourceDate.month()).leftPad(2, '0');
    }

    private static Decimal nullToZero(Decimal sourceValue) {
        return sourceValue == null ? 0 : sourceValue;
    }

    private static Decimal nullToOne(Decimal sourceValue) {
        return sourceValue == null ? 1 : sourceValue;
    }

    private static String normalizeInvoiceAccountItemPicklist(String sourceValue) {
        if (String.isBlank(sourceValue)) {
            return sourceValue;
        }
        if (sourceValue == QUOTATION_ACCOUNT_ITEM_SALES) {
            return INVOICE_ACCOUNT_ITEM_SALES;
        }
        return sourceValue;
    }

    private static void throwIfErrors(List<String> errors) {
        if (!errors.isEmpty()) {
            throw new AuraHandledException(String.join(errors, '\n'));
        }
    }
}

public with sharing class OpportunityMrrSyncService {
    private static final String DEFAULT_CONTRACT_UPDATE = '月';

    public static void syncFromQuotations(
        List<Quotation__c> newRecords,
        List<Quotation__c> oldRecords
    ) {
        Set<Id> opportunityIds = new Set<Id>();
        collectOpportunityIdsFromQuotations(newRecords, opportunityIds);
        collectOpportunityIdsFromQuotations(oldRecords, opportunityIds);
        syncOpportunityMrr(opportunityIds);
    }

    public static void syncFromQuotationLines(
        List<QuotationLine__c> newRecords,
        List<QuotationLine__c> oldRecords
    ) {
        Set<Id> quotationIds = new Set<Id>();
        collectQuotationIds(newRecords, quotationIds);
        collectQuotationIds(oldRecords, quotationIds);

        if (quotationIds.isEmpty()) {
            return;
        }

        Set<Id> opportunityIds = new Set<Id>();
        for (Quotation__c quotation : [
            SELECT Id, Oppotunity__c
            FROM Quotation__c
            WHERE Id IN :quotationIds
        ]) {
            if (quotation.Oppotunity__c != null) {
                opportunityIds.add(quotation.Oppotunity__c);
            }
        }

        syncOpportunityMrrFromQuotationLines(opportunityIds);
    }

    private static void syncOpportunityMrr(Set<Id> opportunityIds) {
        if (opportunityIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> totalByOpportunityId = new Map<Id, Decimal>();
        for (AggregateResult result : [
            SELECT Oppotunity__c opportunityId, SUM(TotalAmount__c) totalAmount
            FROM Quotation__c
            WHERE Oppotunity__c IN :opportunityIds
            GROUP BY Oppotunity__c
        ]) {
            totalByOpportunityId.put(
                (Id) result.get('opportunityId'),
                (Decimal) result.get('totalAmount')
            );
        }

        updateOpportunityMrr(opportunityIds, totalByOpportunityId);
    }

    private static void syncOpportunityMrrFromQuotationLines(Set<Id> opportunityIds) {
        if (opportunityIds.isEmpty()) {
            return;
        }

        Map<Id, Decimal> totalByOpportunityId = new Map<Id, Decimal>();
        for (AggregateResult result : [
            SELECT Quotation__r.Oppotunity__c opportunityId, SUM(Line_Amount__c) totalAmount
            FROM QuotationLine__c
            WHERE Quotation__r.Oppotunity__c IN :opportunityIds
            GROUP BY Quotation__r.Oppotunity__c
        ]) {
            totalByOpportunityId.put(
                (Id) result.get('opportunityId'),
                (Decimal) result.get('totalAmount')
            );
        }

        updateOpportunityMrr(opportunityIds, totalByOpportunityId);
    }

    private static void updateOpportunityMrr(
        Set<Id> opportunityIds,
        Map<Id, Decimal> totalByOpportunityId
    ) {
        if (opportunityIds.isEmpty()) {
            return;
        }

        List<Opportunity__c> opportunitiesToUpdate = new List<Opportunity__c>();
        for (Opportunity__c opportunityRecord : [
            SELECT Id, ContractUpdate__c
            FROM Opportunity__c
            WHERE Id IN :opportunityIds
        ]) {
            Opportunity__c opportunityToUpdate = new Opportunity__c(
                Id = opportunityRecord.Id,
                MRR__c = totalByOpportunityId.containsKey(opportunityRecord.Id)
                    ? totalByOpportunityId.get(opportunityRecord.Id)
                    : 0
            );
            if (String.isBlank(opportunityRecord.ContractUpdate__c)) {
                opportunityToUpdate.ContractUpdate__c = DEFAULT_CONTRACT_UPDATE;
            }
            opportunitiesToUpdate.add(opportunityToUpdate);
        }

        if (!opportunitiesToUpdate.isEmpty()) {
            Database.SaveResult[] results = Database.update(opportunitiesToUpdate, false);
            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    System.debug(
                        LoggingLevel.ERROR,
                        'Opportunity MRR sync failed. OpportunityId='
                        + opportunitiesToUpdate[i].Id
                        + ', Error='
                        + summarizeDmlErrors(results[i].getErrors())
                    );
                }
            }
        }
    }

    private static String summarizeDmlErrors(Database.Error[] errors) {
        List<String> messages = new List<String>();
        for (Database.Error error : errors) {
            messages.add(error.getStatusCode() + ': ' + error.getMessage());
        }
        return String.join(messages, '\n');
    }

    private static void collectOpportunityIdsFromQuotations(
        List<Quotation__c> records,
        Set<Id> opportunityIds
    ) {
        if (records == null) {
            return;
        }

        for (Quotation__c record : records) {
            if (record.Oppotunity__c != null) {
                opportunityIds.add(record.Oppotunity__c);
            }
        }
    }

    private static void collectQuotationIds(
        List<QuotationLine__c> records,
        Set<Id> quotationIds
    ) {
        if (records == null) {
            return;
        }

        for (QuotationLine__c record : records) {
            if (record.Quotation__c != null) {
                quotationIds.add(record.Quotation__c);
            }
        }
    }
}
